mapper.sql:
select distinct decode(reg.is_cancel,'Y','撤销','N','有效') as effectiveStatusStr, decode(reg.finprod_type2,'F01','01','F02','02','F03','02') as finprodType2, btm.busi_type busiTypePosition, reg.finprod_id as finprodId, nvl(fp.finprod_market_id,reg.term_type) as finprodMarketId, fp.finprod_abbr as finprodAbbr, reg.ps as ps, reg.trade_market as tradeMarket, decode(reg.settle_speed,0,'01',1,'02',2,'03') as settleSpeed, reg.sec_manage_acct_id as secManageAcctId, stlinfo.sec_acct_name as secManageAcctIdStr, decode(reg.finprod_type2,'F01',deal.faceValue,null) as faceValue, case when reg.finprod_type2='F01' then decode(regAdd.CAL_MODE,'01',TO_CHAR(ROUND(reg.unit_cprice,4),'FM990.0000'), '02',TO_CHAR(ROUND(reg.yield*100,4),'FM990.0000') ||'%', '03',TO_CHAR(ROUND(reg.exer_yield*100,4),'FM990.0000')||'%') when reg.finprod_type2 in ('F02','F03') then TO_CHAR(ROUND(reg.rate*100,4),'FM990.0000') ||'%' else null end as tradeYield, reg.repo_term as termDays, deal.tradeAmt as tradeAmt, reg.totle_trade_id as busiCode, COALESCE ( sua.IBU_TRADER, su.real_name, reg.ou_trader_id ) AS trader, to_char(reg.trade_date,'yyyy-MM-dd') as regTradeDate, to_char(total.trade_date,'yyyy-MM-dd') as confirmTradeDate, reg.counter_id as counterId, mcci.counter_name as counterIdStr, deal.portfolioId as portfolioIds, deal.portfolioName as portfolioNames, reg.quote_type as quoteType, nvl(match.match_status,'02') as matchStatus, CASE WHEN fpl.ISSUE_CLASS =#{ISSUE_CLASS_01} THEN fp.ISSUE_TYPE ELSE '' END issueType, reg.remark as remark, decode(reg.is_cancel,'Y','03','N','01') effectiveStatus, case when match.trd_conf_status is null and reg.is_cancel='N' then '01' when match.trd_conf_status='1' and reg.is_cancel='N' then '02' when reg.is_cancel='Y' then '03' end as regStatus, regAdd.CAL_MODE calMode from reg_fin_product_deal_total reg left join reg_fin_product_deal_total_add regAdd on reg.totle_trade_id=regAdd.Totle_Trade_Id left join FIN_PRODUCT_ISSUE fpl on reg.finprod_id=fpl.finprod_id left join fin_product fp on fp.finprod_id=reg.finprod_id inner join ( select regdeal.totle_trade_id,wm_concat(regdeal.portfolio_id) as portfolioId,wm_concat(pp.portfolio_name) portfolioName, sum(regdeal.face_value)/10000 as faceValue, sum(regdeal.trade_amt) as tradeAmt from reg_fin_product_deal regdeal inner join ptl_portfolio pp on regdeal.portfolio_id=pp.portfolio_id
inner JOIN PTL_PORTFOLIO_AUTHORITY PPA ON regdeal.portfolio_id = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userId}
where 1=1
AND regdeal.portfolio_id in
#{item}
group by regdeal.totle_trade_id )deal on reg.totle_trade_id=deal.totle_trade_id left join trdquto_match_info match on reg.totle_trade_id=match.pre_trade_id left join trd_fin_product_deal_total total on match.trd_id=total.totle_trade_id left join stl_sec_acct_info stlinfo on reg.sec_manage_acct_id=stlinfo.sec_acct_id LEFT JOIN MST_COUNTER_PARTY mcci ON reg.counter_id= mcci.counter_id left join sys_user su on reg.ou_trader_id=su.user_name LEFT JOIN SYS_USER_ADD sua ON sua.USER_ID = su.USER_ID LEFT JOIN (select INPUT_VALUE_1 as Finprod_Type_Tg,INPUT_VALUE_2 as ps, INPUT_VALUE_3 AS issueClass, OUTPUT_VALUE_1 as busi_type from FIN_PRODUCT_TYPE_CONFIG where CONFIG_TYPE='BUSI_TYPE_MAPPING') btm ON reg.finprod_type2 = btm.Finprod_Type_Tg AND reg.Ps = btm.ps AND (btm.issueClass = fpl.ISSUE_CLASS OR btm.issueClass IS NULL ) where 1=1 and reg.ps in ('T01','T02','T03','03','04') and reg.trade_status='01'
AND reg.trade_date= #{sysDate,jdbcType=DATE}
AND reg.trade_date>= #{startDate,jdbcType=DATE}
AND reg.trade_date<=#{endDate,jdbcType=DATE}
and (reg.create_user= #{submitUserId} or reg.update_user= #{submitUserId})
AND reg.ps=#{ps}
AND reg.finprod_type2 in
#{item}
AND nvl(reg.finprod_id,reg.term_type) in
#{item}
AND btm.busi_type in
#{item}
AND reg.trade_market=#{tradeMarket,jdbcType=VARCHAR}
AND reg.settle_speed = #{settleSpeed,jdbcType=VARCHAR}
AND reg.sec_manage_acct_id in
#{item}
AND reg.totle_trade_id like '%' || #{busiCode,jdbcType=VARCHAR} || '%'
AND nvl(match.match_status,'02') = #{matchStatus,jdbcType=VARCHAR}
AND reg.quote_type= #{quoteType,jdbcType=VARCHAR}
AND reg.counter_id= #{counterId,jdbcType=VARCHAR}
AND (case when match.trd_conf_status is null and reg.is_cancel='N' then '01' when match.trd_conf_status='1' and reg.is_cancel='N' then '02' when reg.is_cancel='Y' then '03' end) in
#{item}

SELECT distinct decode(BO.IS_CANCEL,'Y','撤销','N','有效') effectiveStatusStr, FPT.TYPE_9 AS finprodType2, CASE WHEN FPI.ISSUE_CLASS IN(#{ISSUE_CLASS_02},#{ISSUE_CLASS_03}) THEN #{BUSI_TYPE_POSITION_01} WHEN FPI.ISSUE_CLASS = #{ISSUE_CLASS_01} THEN #{BUSI_TYPE_POSITION_34} END AS busiTypePosition, FP.finprod_id as finprodId, FP.FINPROD_MARKET_ID AS finprodMarketId, FP.FINPROD_ABBR AS finprodAbbr, #{PS_T01} AS ps, FP.TRADE_MARKET AS tradeMarket, null AS settleSpeed, BRBP.SEC_ACCT_ID AS secManageAcctId, BRBP.SEC_ACCT_NAME AS secManageAcctIdStr, CASE WHEN FPI.ISSUE_CLASS IN(#{ISSUE_CLASS_02},#{ISSUE_CLASS_03}) THEN BO.WIN_PRIN_AMT/10000 WHEN FPI.ISSUE_CLASS = #{ISSUE_CLASS_01} THEN BO.SUBSCRIPTION_AMOUNT/10000 END AS faceValue, CASE WHEN FPI.ISSUE_CLASS IN(#{ISSUE_CLASS_02},#{ISSUE_CLASS_03}) THEN BRBP.BID_PRICE WHEN FPI.ISSUE_CLASS = #{ISSUE_CLASS_01} THEN TO_CHAR(ROUND(FPI.REFER_YIELD,4),'FM99999990.0000') END AS tradeYield, null AS termDays, CASE WHEN FPI.ISSUE_CLASS IN(#{ISSUE_CLASS_02},#{ISSUE_CLASS_03}) THEN null WHEN FPI.ISSUE_CLASS = #{ISSUE_CLASS_01} THEN BO.PAYABLE_AMOUNT END AS tradeAmt, BO.BID_ID AS busiCode, BO.OUR_TRADER AS trader, to_char(BO.BID_DATE,'yyyy-MM-dd') AS regTradeDate, to_char(BO.BID_DATE,'yyyy-MM-dd') AS confirmTradeDate, BO.COUNTER_ID AS counterId, MCCI.COUNTER_NAME AS counterIdStr, BRBP.PORTFOLIO_ID AS portfolioIds, BRBP.PORTFOLIO_NAME AS portfolioNames, '' AS quoteType, '' AS matchStatus, CASE WHEN FPI.ISSUE_CLASS =#{ISSUE_CLASS_01} THEN FP.ISSUE_TYPE ELSE '' END issueType, BO.REMARK AS remark, decode(BO.IS_CANCEL,'Y','03','N','01') effectiveStatus, case when (BO.IS_CANCEL = 'N' AND ( BO.BID_MODLE = #{WIN_TYPE_03} OR (BO.BID_MODLE IN (#{WIN_TYPE_01},#{WIN_TYPE_02})AND BRT.TOTAL_WIN_ID IS NOT NULL) OR (FPI.ISSUE_CLASS=#{ISSUE_CLASS_01} AND TMI.PRE_TRADE_ID IS NOT NULL))) then '01' when (BO.IS_CANCEL = 'N' AND ( (BO.BID_MODLE IN (#{WIN_TYPE_01},#{WIN_TYPE_02})AND BRT.TOTAL_WIN_ID IS NULL)OR (FPI.ISSUE_CLASS=#{ISSUE_CLASS_01} AND TMI.PRE_TRADE_ID IS NULL))) then '02' end AS regStatus, '' calMode FROM BID_ORDER BO LEFT JOIN (SELECT BRBP.BID_ID,wm_concat(BRBP.SEC_ACCT_ID) SEC_ACCT_ID, wm_concat(STLINFO.SEC_ACCT_NAME) SEC_ACCT_NAME, wm_concat(BRBP.PORTFOLIO_ID) PORTFOLIO_ID, wm_concat(PP.PORTFOLIO_NAME) PORTFOLIO_NAME, wm_concat(TO_CHAR(ROUND(BRBP.BID_PRICE,4),'FM9999990.0000')) BID_PRICE FROM BID_ORDER_BID_PRICE BRBP LEFT JOIN PTL_PORTFOLIO PP ON PP.PORTFOLIO_ID = BRBP.PORTFOLIO_ID LEFT JOIN STL_SEC_ACCT_INFO STLINFO ON BRBP.SEC_ACCT_ID=STLINFO.SEC_ACCT_ID where 1=1
AND BRBP.SEC_ACCT_ID in
#{item}
GROUP BY BRBP.BID_ID ) BRBP ON BRBP.BID_ID = BO.BID_ID LEFT JOIN FIN_PRODUCT FP ON FP.FINPROD_ID = BO.FINPROD_ID LEFT JOIN FIN_PRODUCT_ISSUE FPI ON FPI.FINPROD_ID = FP.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE FPT ON FPT.FINPROD_ID = FP.FINPROD_ID LEFT JOIN MST_COUNTER_PARTY MCCI ON BO.COUNTER_ID= MCCI.COUNTER_ID LEFT JOIN BID_RESULT_TOTAL BRT ON BRT.FINPROD_ID = FP.FINPROD_ID AND BRT.BID_ID = BO.BID_ID AND BRT.STATUS = #{STATUS_VALID_01} LEFT JOIN TRDQUTO_MATCH_INFO TMI ON TMI.PRE_TRADE_ID = BO.BID_ID WHERE BO.TRADE_STATUS = #{TRADE_STATUS_01} AND FP.TRADE_MARKET IN (#{TRADE_PLACE_01},#{TRADE_PLACE_01})
AND BO.BID_DATE = #{sysDate}
AND BO.BID_DATE>= #{startDate,jdbcType=DATE}
AND BO.BID_DATE<=#{endDate,jdbcType=DATE}
and (BO.create_user= #{submitUserId} or BO.update_user= #{submitUserId})
AND #{PS_T01} =#{ps}
AND FPT.TYPE_9 in
#{item}
AND BO.FINPROD_ID IN
#{item}
AND ( CASE WHEN FPI.ISSUE_CLASS IN(#{ISSUE_CLASS_02},#{ISSUE_CLASS_03}) THEN #{BUSI_TYPE_POSITION_01} WHEN FPI.ISSUE_CLASS = #{ISSUE_CLASS_01} THEN #{BUSI_TYPE_POSITION_34} END ) IN
#{item}
AND FP.TRADE_MARKET=#{tradeMarket,jdbcType=VARCHAR}
AND 1 != 1
AND BO.BID_ID like '%' || #{busiCode,jdbcType=VARCHAR} || '%'
AND 1 != 1
AND 1 != 1
AND BO.COUNTER_ID= #{counterId,jdbcType=VARCHAR}
AND (case when (BO.IS_CANCEL = 'N' AND ( BO.BID_MODLE = #{WIN_TYPE_03} OR (BO.BID_MODLE IN (#{WIN_TYPE_01},#{WIN_TYPE_02})AND BRT.TOTAL_WIN_ID IS NOT NULL) OR (FPI.ISSUE_CLASS=#{ISSUE_CLASS_01} AND TMI.PRE_TRADE_ID IS NOT NULL))) then '01' when (BO.IS_CANCEL = 'N' AND ( (BO.BID_MODLE IN (#{WIN_TYPE_01},#{WIN_TYPE_02})AND BRT.TOTAL_WIN_ID IS NULL)OR (FPI.ISSUE_CLASS=#{ISSUE_CLASS_01} AND TMI.PRE_TRADE_ID IS NULL))) then '02' end) in
#{item}

SELECT '流程中' effectiveStatusStr, FPT.TYPE_9 AS finprodType2, CASE WHEN FPI.ISSUE_CLASS IN(#{ISSUE_CLASS_02},#{ISSUE_CLASS_03}) THEN #{BUSI_TYPE_POSITION_01} WHEN FPI.ISSUE_CLASS = #{ISSUE_CLASS_01} THEN #{BUSI_TYPE_POSITION_34} END AS busiTypePosition, FP.FINPROD_ID as finprodId, FP.FINPROD_MARKET_ID AS finprodMarketId, FP.finprod_abbr as finprodAbbr, #{PS_T01} AS ps, FP.TRADE_MARKET AS tradeMarket, null AS settleSpeed, WBRBP.SEC_ACCT_ID AS secManageAcctId, WBRBP.SEC_ACCT_NAME AS secManageAcctIdStr, CASE WHEN FPI.ISSUE_CLASS IN(#{ISSUE_CLASS_02},#{ISSUE_CLASS_03}) THEN WBO.WIN_PRIN_AMT/10000 WHEN FPI.ISSUE_CLASS = #{ISSUE_CLASS_01} THEN WBO.SUBSCRIPTION_AMOUNT/10000 END AS faceValue, CASE WHEN FPI.ISSUE_CLASS IN(#{ISSUE_CLASS_02},#{ISSUE_CLASS_03}) THEN WBRBP.BID_PRICE WHEN FPI.ISSUE_CLASS = #{ISSUE_CLASS_01} THEN TO_CHAR(ROUND(FPI.REFER_YIELD,4),'FM990.0000') END AS tradeYield, null AS termDays, CASE WHEN FPI.ISSUE_CLASS IN(#{ISSUE_CLASS_02},#{ISSUE_CLASS_03}) THEN null WHEN FPI.ISSUE_CLASS = #{ISSUE_CLASS_01} THEN WBO.PAYABLE_AMOUNT END AS tradeAmt, WBO.BID_ID AS busiCode, WBO.OUR_TRADER AS trader, to_char(WBO.BID_DATE,'yyyy-MM-dd') AS regTradeDate, to_char(WBO.BID_DATE,'yyyy-MM-dd') AS confirmTradeDate, WBO.COUNTER_ID AS counterId, MCCI.COUNTER_NAME AS counterIdStr, WBRBP.PORTFOLIO_ID AS portfolioIds, WBRBP.PORTFOLIO_NAME AS portfolioNames, '' AS quoteType, '' AS matchStatus, CASE WHEN FPI.ISSUE_CLASS =#{ISSUE_CLASS_01} THEN FP.ISSUE_TYPE ELSE '' END issueType, WBO.REMARK AS remark, #{STATUS_VALID_04} effectiveStatusStr, '04' AS regStatus, '' calMode FROM WFL_BID_ORDER WBO LEFT JOIN (SELECT WBRBP.BID_ID,wm_concat(WBRBP.SEC_ACCT_ID) SEC_ACCT_ID, wm_concat(STLINFO.SEC_ACCT_NAME) SEC_ACCT_NAME, wm_concat(WBRBP.PORTFOLIO_ID) PORTFOLIO_ID, wm_concat(PP.PORTFOLIO_NAME) PORTFOLIO_NAME, wm_concat(TO_CHAR(ROUND(WBRBP.BID_PRICE,4),'FM990.0000')) BID_PRICE FROM WFL_BID_ORDER_BID_PRICE WBRBP LEFT JOIN PTL_PORTFOLIO PP ON PP.PORTFOLIO_ID = WBRBP.PORTFOLIO_ID LEFT JOIN STL_SEC_ACCT_INFO STLINFO ON WBRBP.SEC_ACCT_ID=STLINFO.SEC_ACCT_ID where 1=1
AND BRBP.SEC_ACCT_ID in
#{item}
GROUP BY WBRBP.BID_ID ) WBRBP ON WBRBP.BID_ID = WBO.BID_ID LEFT JOIN FIN_PRODUCT FP ON FP.FINPROD_ID = WBO.FINPROD_ID LEFT JOIN FIN_PRODUCT_ISSUE FPI ON FPI.FINPROD_ID = FP.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE FPT ON FPT.FINPROD_ID = FP.FINPROD_ID LEFT JOIN MST_COUNTER_PARTY mcci ON WBO.COUNTER_ID= mcci.COUNTER_ID WHERE FP.TRADE_MARKET IN (#{TRADE_PLACE_01},#{TRADE_PLACE_02})
AND WBO.BID_DATE = #{sysDate}
AND WBO.BID_DATE>= #{startDate,jdbcType=DATE}
AND WBO.BID_DATE<=#{endDate,jdbcType=DATE}
and (WBO.create_user= #{submitUserId} or WBO.update_user= #{submitUserId})
AND #{PS_T01} =#{ps}
AND FPT.TYPE_9 in
#{item}
AND WBO.FINPROD_ID IN
#{item}
AND (CASE WHEN FPI.ISSUE_CLASS IN(#{ISSUE_CLASS_02},#{ISSUE_CLASS_03}) THEN #{BUSI_TYPE_POSITION_01} WHEN FPI.ISSUE_CLASS = #{ISSUE_CLASS_01} THEN #{BUSI_TYPE_POSITION_34} END) in
#{item}
AND FP.TRADE_MARKET=#{tradeMarket,jdbcType=VARCHAR}
AND 1 != 1
AND WBO.BID_ID like '%' || #{busiCode,jdbcType=VARCHAR} || '%'
AND 1 != 1
AND 1 != 1
AND WBO.COUNTER_ID= #{counterId,jdbcType=VARCHAR}
AND '04' in
#{item}

select distinct '流程中' as effectiveStatusStr, decode(reg.finprod_type2,'F01','01','F02','02','F03','02') as finprodType2, btm.busi_type busiTypePosition, reg.finprod_id as finprodId, nvl(fp.finprod_market_id,reg.term_type) as finprodMarketId, fp.finprod_abbr as finprodAbbr, reg.ps as ps, reg.trade_market as tradeMarket, decode(reg.settle_speed,0,'01',1,'02',2,'03') as settleSpeed, reg.sec_manage_acct_id as secManageAcctId, stlinfo.sec_acct_name as secManageAcctIdStr, decode(reg.finprod_type2,'F01',deal.faceValue,null) as faceValue, case when reg.finprod_type2='F01' then decode(regAdd.CAL_MODE,'01',TO_CHAR(ROUND(reg.unit_cprice,4),'FM990.0000'), '02',TO_CHAR(ROUND(reg.yield*100,4),'FM990.0000') ||'%', '03',TO_CHAR(ROUND(reg.exer_yield*100,4),'FM990.0000')||'%') when reg.finprod_type2 in ('F02','F03') then TO_CHAR(ROUND(reg.rate*100,4),'FM990.0000') ||'%' else null end as tradeYield, reg.repo_term as termDays, deal.tradeAmt as tradeAmt, reg.totle_trade_id as busiCode, reg.ou_trader_id as trader, to_char(reg.trade_date,'yyyy-MM-dd') as regTradeDate, null as confirmTradeDate, reg.counter_id as counterId, mcci.counter_name as counterIdStr, deal.portfolioId as portfolioIds, deal.portfolioName as portfolioNames, reg.quote_type as quoteType, nvl(match.match_status,'02') as matchStatus, CASE WHEN fpl.ISSUE_CLASS =#{ISSUE_CLASS_01} THEN fp.ISSUE_TYPE ELSE '' END issueType, reg.remark as remark, '04' effectiveStatus, '04' as regStatus, regAdd.CAL_MODE calMode from wfl_reg_fin_product_deal_total reg left join wfl_reg_fin_pro_deal_total_add regAdd on reg.totle_trade_id=regAdd.Totle_Trade_Id left join FIN_PRODUCT_ISSUE fpl on reg.finprod_id=fpl.finprod_id left join fin_product fp on fp.finprod_id=reg.finprod_id inner join ( select regdeal.totle_trade_id,wm_concat(regdeal.portfolio_id) as portfolioId,wm_concat(pp.portfolio_name) portfolioName, sum(regdeal.face_value)/10000 as faceValue, sum(regdeal.trade_amt) as tradeAmt from wfl_reg_fin_product_deal regdeal inner join ptl_portfolio pp on regdeal.portfolio_id=pp.portfolio_id
inner JOIN PTL_PORTFOLIO_AUTHORITY PPA ON regdeal.portfolio_id = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userId}
where 1=1
AND regdeal.portfolio_id in
#{item}
group by regdeal.totle_trade_id )deal on reg.totle_trade_id=deal.totle_trade_id left join trdquto_match_info match on reg.totle_trade_id=match.pre_trade_id left join stl_sec_acct_info stlinfo on reg.sec_manage_acct_id=stlinfo.sec_acct_id LEFT JOIN MST_COUNTER_PARTY mcci ON reg.counter_id= mcci.counter_id LEFT JOIN (select INPUT_VALUE_1 as Finprod_Type_Tg,INPUT_VALUE_2 as ps, INPUT_VALUE_3 AS issueClass, OUTPUT_VALUE_1 as busi_type from FIN_PRODUCT_TYPE_CONFIG where CONFIG_TYPE='BUSI_TYPE_MAPPING') btm ON reg.finprod_type2 = btm.Finprod_Type_Tg AND reg.Ps = btm.ps AND (btm.issueClass = fpl.ISSUE_CLASS OR btm.issueClass IS NULL ) where reg.ps in ('T01','T02','T03','03','04')
AND reg.trade_date= #{sysDate,jdbcType=DATE}
AND reg.trade_date>= #{startDate,jdbcType=DATE}
AND reg.trade_date<=#{endDate,jdbcType=DATE}
and (reg.create_user= #{submitUserId} or reg.update_user= #{submitUserId})
AND reg.ps=#{ps}
AND reg.finprod_type2 in
#{item}
AND nvl(reg.finprod_id,reg.term_type) in
#{item}
AND btm.busi_type in
#{item}
AND reg.trade_market=#{tradeMarket,jdbcType=VARCHAR}
AND reg.settle_speed = #{settleSpeed,jdbcType=VARCHAR}
AND reg.sec_manage_acct_id in
#{item}
AND reg.totle_trade_id like '%' || #{busiCode,jdbcType=VARCHAR} || '%'
AND nvl(match.match_status,'02') = #{matchStatus,jdbcType=VARCHAR}
AND reg.quote_type= #{quoteType,jdbcType=VARCHAR}
AND reg.counter_id= #{counterId,jdbcType=VARCHAR}
AND '04' in
#{item}

where.if:
and ((aaa.effectiveStatusStr || '|' || sdl.ITEM_VALUE || '|' || '|' || sdlbusiTypePosition.ITEM_VALUE || '|' || aaa.finprodMarketId || '|' || aaa.finprodAbbr
|| '|' || dictps.ITEM_VALUE || '|' || dicttradeMarket.ITEM_VALUE || '|' || dictsp.ITEM_VALUE
|| '|' || aaa.secManageAcctIdStr || '|' || aaa.busiCode || '|' || aaa.trader
|| '|' || aaa.counterId  || '|' || aaa.counterIdStr || '|' || aaa.portfolioIds  || '|' || aaa.portfolioNames
|| '|' || dictquote.ITEM_VALUE  || '|' || dictms.ITEM_VALUE || '|' || aaa.remark
like '%' || #{search} || '%')
or to_char(aaa.faceValue,'FM9999999999999990.90')=#{search} or to_char(aaa.faceValue)=#{search}
or aaa.tradeYield =#{search} or aaa.tradeYield =#{search}||'%'
or aaa.termDays||'' =#{search}
or to_char(aaa.tradeAmt,'FM9999999999999990.90')=#{search} or to_char(aaa.tradeAmt)=#{search}
or aaa.regTradeDate||'' =#{search}
or aaa.regTradeDate||'' =#{year}||'-'||#{search}
or replace(aaa.regTradeDate,'-','/')||'' =#{search}
or replace(aaa.regTradeDate,'-','/')||'' =#{year}||'/'||#{search}
or aaa.confirmTradeDate||'' =#{search}
or aaa.confirmTradeDate||'' =#{year}||'-'||#{search}
or replace(aaa.confirmTradeDate,'-','/')||'' =#{search}
or replace(aaa.confirmTradeDate,'-','/')||'' =#{year}||'/'||#{search}
)

mapper.select:
select distinct reg.ou_party_id as traderid, m1.PARTY_ABBR as traderidStr, COALESCE (sua.IBU_TRADER, su.real_name, reg.ou_trader_id) AS trader, reg.counter_id as counterId, m2.counter_name as counterIdStr, nvl(su1.TRADER_NAME,reg.counter_trader) as counterTrader, reg.finprod_id as finprodId, fp.finprod_market_id as finprodMarketId, fp.finprod_abbr as finprodAbbr, reg.ps as ps, reg.quote_type as quoteType, to_char(reg.trade_date,'yyyy-MM-dd') as regTradeDate, decode(reg.settle_speed,0,'01',1,'02',2,'03') as settleSpeed, to_char(reg.settle_date,'yyyy-MM-dd') as settleDate, reg.ccy as ccy, reg.unit_cprice as unitCprice, reg.yield*100 as yield, reg.exer_yield*100 as exerYield, nvl(deal.faceValue,reg.face_value/10000) as faceValue, reg.delivery_type deliveryType, reg.clear_type as clearType, deal.trdFeeAmt as trdFeeAmt, deal.settleFeeAmt as settleFeeAmt, reg.unit_int as unitInt, reg.unit_fprice as unitFprice, deal.cpriceAmt as cpriceAmt, deal.intAmt as intAmt, deal.fpriceAmt as fpriceAmt, reg.dip_type as distriType, reg.remark as remark, to_char(reg.settle_date,'yyyy-MM-dd') as exerciseDate, to_char(regAdd.Act_Sette_Date,'yyyy-MM-dd') as acrExerciseDate, reg.unit_cprice as exercisePrice, reg.repo_term as repoTerm, reg.rate*100 as tradeYield, reg.ccy as secCcy, reg.sett_ccy settCcy, reg.trade_amt tradeAmt, deal.disFaceValue as disFaceValue, reg.m_delivery_type mdeliveryType, to_char(reg.v_settle_date,'yyyy-MM-dd') as vsettleDate, to_char(reg.m_settle_date,'yyyy-MM-dd') as msettleDate, deal.mtradeAmt as mtradeAmt, reg.act_repo_term actRepoTerm, reg.term_type as termType from reg_fin_product_deal_total reg left join fin_product fp on fp.finprod_id=reg.finprod_id left join reg_fin_product_deal_total_add regAdd on reg.totle_trade_id=regAdd.Totle_Trade_Id inner join ( select regdeal.totle_trade_id, sum(regdeal.face_value)/10000 as faceValue, sum(decode(regdeal.finprod_type2,'F01',regdeal.int_amt,'F02',regdeal.m_int_amt,'F03',regdeal.m_int_amt)) as intAmt, sum(regdeal.cprice_amt) as cpriceAmt, sum(regdeal.fprice_amt) as fpriceAmt, sum(regdeal.trade_amt) as tradeAmt, sum(regdeal.dis_face_value) as disFaceValue, sum(regdeal.m_trade_amt) as mtradeAmt, sum(feeDeal.trdFeeAmt) as trdFeeAmt, sum(feeDeal.settleFeeAmt) as settleFeeAmt from reg_fin_product_deal regdeal inner join ptl_portfolio pp on regdeal.portfolio_id=pp.portfolio_id
inner JOIN PTL_PORTFOLIO_AUTHORITY PPA ON regdeal.portfolio_id = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userId}
left join ( select rf.trade_id,sum(decode(rf.fee_type,'B06',rf.fee_amt)) as trdFeeAmt, sum(decode(rf.fee_type,'B08',rf.fee_amt)) as settleFeeAmt from reg_trade_fee rf group by rf.trade_id )feeDeal on regdeal.trade_id=feeDeal.trade_id where regdeal.totle_trade_id=#{totleTradeId,jdbcType=VARCHAR} group by regdeal.totle_trade_id )deal on reg.totle_trade_id=deal.totle_trade_id left join MST_CFETS_CUSTOMER_INFO m1 on reg.ou_party_id=m1.PARTY_ID LEFT JOIN MST_COUNTER_PARTY m2 ON reg.counter_id= m2.counter_id left join sys_user su on reg.ou_trader_id=su.user_name LEFT JOIN SYS_USER_ADD sua ON sua.USER_ID = su.USER_ID left join MST_CFETS_CUSTOMER_TRADER su1 on reg.counter_trader=su1.TRADER_ID where reg.totle_trade_id= #{totleTradeId,jdbcType=VARCHAR} and decode(reg.is_cancel,'Y','03','N','01')= #{effectiveStatus,jdbcType=VARCHAR} union all select reg.ou_party_id as traderid, m1.PARTY_ABBR as traderidStr, nvl(su.real_name,reg.ou_trader_id) as trader, reg.counter_id as counterId, m2.counter_name as counterIdStr, nvl(su1.TRADER_NAME,reg.counter_trader) as counterTrader, reg.finprod_id as finprodId, fp.finprod_market_id as finprodMarketId, fp.finprod_abbr as finprodAbbr, reg.ps as ps, reg.quote_type as quoteType, to_char(reg.trade_date,'yyyy-MM-dd') as regTradeDate, decode(reg.settle_speed,0,'01',1,'02',2,'03') as settleSpeed, to_char(reg.settle_date,'yyyy-MM-dd') as settleDate, reg.ccy as ccy, reg.unit_cprice as unitCprice, reg.yield*100 as yield, reg.exer_yield*100 as exerYield, nvl(deal.faceValue,reg.face_value/10000) as faceValue, reg.delivery_type deliveryType, reg.clear_type as clearType, deal.trdFeeAmt as trdFeeAmt, deal.settleFeeAmt as settleFeeAmt, reg.unit_int as unitInt, reg.unit_fprice as unitFprice, deal.cpriceAmt as cpriceAmt, deal.intAmt as intAmt, deal.fpriceAmt as fpriceAmt, reg.dip_type as distriType, reg.remark as remark, to_char(reg.settle_date,'yyyy-MM-dd') as exerciseDate, to_char(regAdd.Act_Sette_Date,'yyyy-MM-dd') as acrExerciseDate, reg.unit_cprice as exercisePrice, reg.repo_term as repoTerm, reg.rate*100 as tradeYield, reg.ccy as secCcy, reg.sett_ccy settCcy, reg.trade_amt tradeAmt, deal.disFaceValue as disFaceValue, reg.m_delivery_type mdeliveryType, to_char(reg.v_settle_date,'yyyy-MM-dd') as vsettleDate, to_char(reg.m_settle_date,'yyyy-MM-dd') as msettleDate, deal.mtradeAmt as mtradeAmt, reg.act_repo_term actRepoTerm, reg.term_type as termType from wfl_reg_fin_product_deal_total reg left join fin_product fp on fp.finprod_id=reg.finprod_id left join wfl_reg_fin_pro_deal_total_add regAdd on reg.totle_trade_id=regAdd.Totle_Trade_Id inner join ( select regdeal.totle_trade_id, sum(regdeal.face_value)/10000 as faceValue, sum(decode(regdeal.finprod_type2,'F01',regdeal.int_amt,'F02',regdeal.m_int_amt,'F03',regdeal.m_int_amt)) as intAmt, sum(regdeal.cprice_amt) as cpriceAmt, sum(regdeal.fprice_amt) as fpriceAmt, sum(regdeal.trade_amt) as tradeAmt, sum(regdeal.dis_face_value) as disFaceValue, sum(regdeal.m_trade_amt) as mtradeAmt, sum(feeDeal.trdFeeAmt) as trdFeeAmt, sum(feeDeal.settleFeeAmt) as settleFeeAmt from wfl_reg_fin_product_deal regdeal inner join ptl_portfolio pp on regdeal.portfolio_id=pp.portfolio_id
inner JOIN PTL_PORTFOLIO_AUTHORITY PPA ON regdeal.portfolio_id = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userId}
left join ( select rf.trade_id,sum(decode(rf.fee_type,'B06',rf.fee_amt)) as trdFeeAmt, sum(decode(rf.fee_type,'B08',rf.fee_amt)) as settleFeeAmt from wfl_reg_trade_fee rf group by rf.trade_id )feeDeal on regdeal.trade_id=feeDeal.trade_id where regdeal.totle_trade_id=#{totleTradeId,jdbcType=VARCHAR} group by regdeal.totle_trade_id )deal on reg.totle_trade_id=deal.totle_trade_id left join MST_CFETS_CUSTOMER_INFO m1 on reg.ou_party_id=m1.PARTY_ID LEFT JOIN MST_COUNTER_PARTY m2 ON reg.counter_id= m2.counter_id left join sys_user su on reg.ou_trader_id=su.user_name left join MST_CFETS_CUSTOMER_TRADER su1 on reg.counter_trader=su1.TRADER_ID where reg.totle_trade_id= #{totleTradeId,jdbcType=VARCHAR} and #{STATUS_VALID_04}= #{effectiveStatus,jdbcType=VARCHAR}

select reg.entrust_id as entrustId, reg.portfolio_id as portfolioId, pp.portfolio_name as portfolioName, reg.face_value/10000 as faceValue, feeDeal.trdFeeAmt as trdFeeAmt, feeDeal.settleFeeAmt as settleFeeAmt, reg.cprice_amt as cpriceAmt, decode(reg.finprod_type2,'F01',reg.int_amt,'F02',reg.m_int_amt,'F03',reg.m_int_amt) as intAmt, reg.fprice_amt as fpriceAmt, EE.PRICE_MODEL as priceModel, EE.BUSINESS_MODEL as businessModel, reg.sec_manage_acct_id as secManageAcctId, stlinfo.sec_acct_name as secManageAcctIdStr, reg.unit_cprice as unitCprice, reg.trade_amt as tradeAmt, reg.m_trade_amt as mtradeAmt, reg.dis_face_value as disFaceValue, reg.rate*100 tradeYield, reg.yield*100 as yield, reg.exer_yield*100 as exerYield from reg_fin_product_deal reg inner join ptl_portfolio pp on reg.portfolio_id=pp.portfolio_id
inner JOIN PTL_PORTFOLIO_AUTHORITY PPA ON reg.portfolio_id = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userId}
left join ( select rf.trade_id,sum(decode(rf.fee_type,'B06',rf.fee_amt)) as trdFeeAmt, sum(decode(rf.fee_type,'B08',rf.fee_amt)) as settleFeeAmt from reg_trade_fee rf group by rf.trade_id )feeDeal on reg.trade_id=feeDeal.trade_id LEFT JOIN ETR_ENTRUST ee ON reg.entrust_id = ee.entrust_id left join stl_sec_acct_info stlinfo on reg.sec_manage_acct_id=stlinfo.sec_acct_id where reg.totle_trade_id=#{totleTradeId,jdbcType=VARCHAR} and decode(reg.is_cancel,'Y','03','N','01')= #{effectiveStatus,jdbcType=VARCHAR} union all select reg.entrust_id as entrustId, reg.portfolio_id as portfolioId, pp.portfolio_name as portfolioName, reg.face_value/10000 as faceValue, feeDeal.trdFeeAmt as trdFeeAmt, feeDeal.settleFeeAmt as settleFeeAmt, reg.cprice_amt as cpriceAmt, decode(reg.finprod_type2,'F01',reg.int_amt,'F02',reg.m_int_amt,'F03',reg.m_int_amt) as intAmt, reg.fprice_amt as fpriceAmt, EE.PRICE_MODEL as priceModel, EE.BUSINESS_MODEL as businessModel, reg.sec_manage_acct_id as secManageAcctId, stlinfo.sec_acct_name as secManageAcctIdStr, reg.unit_cprice as unitCprice, reg.trade_amt as tradeAmt, reg.m_trade_amt as mtradeAmt, reg.dis_face_value as disFaceValue, reg.rate*100 tradeYield, reg.yield*100 as yield, reg.exer_yield*100 as exerYield from wfl_reg_fin_product_deal reg inner join ptl_portfolio pp on reg.portfolio_id=pp.portfolio_id
inner JOIN PTL_PORTFOLIO_AUTHORITY PPA ON reg.portfolio_id = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userId}
left join ( select rf.trade_id,sum(decode(rf.fee_type,'B06',rf.fee_amt)) as trdFeeAmt, sum(decode(rf.fee_type,'B08',rf.fee_amt)) as settleFeeAmt from wfl_reg_trade_fee rf group by rf.trade_id )feeDeal on reg.trade_id=feeDeal.trade_id LEFT JOIN ETR_ENTRUST ee ON reg.entrust_id = ee.entrust_id left join stl_sec_acct_info stlinfo on reg.sec_manage_acct_id=stlinfo.sec_acct_id where reg.totle_trade_id=#{totleTradeId,jdbcType=VARCHAR} and #{STATUS_VALID_04}= #{effectiveStatus,jdbcType=VARCHAR}

select rp.pledge_finprod_id as finprodId, fp.finprod_market_id as finprodMarketId, fp.finprod_abbr as finprodAbbr, rp.portfolio_id as portfolioId, pp.portfolio_name as portfolioName, sum(rp.pledge_number)/100 as pledgePrin, rp.pledge_ratio*100 as pledgeRate, mbvi.NETPRICE as firstNetPrice, fp.REGIST_ORG as repRegistOrg, T8.DIS_FACE_VALUE as disFaceValue from REG_FIN_PLEDGE rp left join reg_fin_product_deal regdeal LEFT JOIN wfl_REG_FIN_PRODUCT_DEAL_TOTAL T8 ON T8.TOTLE_TRADE_ID = regdeal.TOTLE_TRADE_ID on rp.trade_id=regdeal.trade_id left join ptl_portfolio pp on pp.portfolio_id=rp.portfolio_id
inner JOIN PTL_PORTFOLIO_AUTHORITY PPA ON rp.portfolio_id = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userId}
left join fin_product fp on fp.finprod_id=rp.pledge_finprod_id LEFT JOIN ( SELECT T2.SEC_ID, T2.PRICE, T2.NETPRICE FROM ( SELECT tmp1.SEC_ID, tmp1.value_source, MAX(tmp1.value_date) AS value_date FROM MST_BOND_VALUATION_INFO tmp1 LEFT JOIN FIN_PRODUCT tmp2 ON tmp1.sec_id = tmp2.finprod_market_id WHERE 1 = 1 AND tmp1.value_date <= to_date(#{platDate},'yyyy-MM-dd')/*估值行情.日期 小于等于 平台日*/ AND tmp1.value_source = ( CASE WHEN tmp2.trade_market IN (#{TRADEPLACE03},#{TRADEPLACE04}) THEN 'CSD' ELSE 'CBC' END) GROUP BY tmp1.sec_id, tmp1.value_source ) T1 LEFT JOIN MST_BOND_VALUATION_INFO T2 ON T1.SEC_ID = T2.SEC_ID AND T1.value_source = T2.value_source AND T1.VALUE_DATE = T2.VALUE_DATE ) mbvi/*以上获取债券小于等于平台日的最新估值行情*/ ON fp.FINPROD_MARKET_ID = mbvi.SEC_ID where regdeal.totle_trade_id=#{totleTradeId,jdbcType=VARCHAR} and decode(regdeal.is_cancel,'Y','03','N','01')= #{effectiveStatus,jdbcType=VARCHAR} group by rp.pledge_finprod_id, fp.finprod_market_id, fp.finprod_abbr, rp.portfolio_id, pp.portfolio_name, rp.pledge_ratio, mbvi.NETPRICE, fp.REGIST_ORG, T8.DIS_FACE_VALUE union all select rp.pledge_finprod_id as finprodId, fp.finprod_market_id as finprodMarketId, fp.finprod_abbr as finprodAbbr, rp.portfolio_id as portfolioId, pp.portfolio_name as portfolioName, sum(rp.pledge_number)/100 as pledgePrin, rp.pledge_ratio*100 as pledgeRate, mbvi.NETPRICE as firstNetPrice, fp.REGIST_ORG as repRegistOrg, T8.DIS_FACE_VALUE as disFaceValue from wfl_REG_FIN_PLEDGE rp left join wfl_reg_fin_product_deal regdeal on rp.trade_id=decode(regdeal.finprod_type2,'F02',regdeal.trade_id,'F03',regdeal.totle_trade_id) LEFT JOIN wfl_REG_FIN_PRODUCT_DEAL_TOTAL T8 ON T8.TOTLE_TRADE_ID = regdeal.TOTLE_TRADE_ID left join ptl_portfolio pp on pp.portfolio_id=rp.portfolio_id
inner JOIN PTL_PORTFOLIO_AUTHORITY PPA ON rp.portfolio_id = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userId}
left join fin_product fp on fp.finprod_id=rp.pledge_finprod_id LEFT JOIN ( SELECT T2.SEC_ID, T2.PRICE, T2.NETPRICE FROM ( SELECT tmp1.SEC_ID, tmp1.value_source, MAX(tmp1.value_date) AS value_date FROM MST_BOND_VALUATION_INFO tmp1 LEFT JOIN FIN_PRODUCT tmp2 ON tmp1.sec_id = tmp2.finprod_market_id WHERE 1 = 1 AND tmp1.value_date <= to_date(#{platDate},'yyyy-MM-dd')/*估值行情.日期 小于等于 平台日*/ AND tmp1.value_source = ( CASE WHEN tmp2.trade_market IN (#{TRADEPLACE03},#{TRADEPLACE04}) THEN 'CSD' ELSE 'CBC' END) GROUP BY tmp1.sec_id, tmp1.value_source ) T1 LEFT JOIN MST_BOND_VALUATION_INFO T2 ON T1.SEC_ID = T2.SEC_ID AND T1.value_source = T2.value_source AND T1.VALUE_DATE = T2.VALUE_DATE ) mbvi/*以上获取债券小于等于平台日的最新估值行情*/ ON fp.FINPROD_MARKET_ID = mbvi.SEC_ID where regdeal.totle_trade_id=#{totleTradeId,jdbcType=VARCHAR} and #{STATUS_VALID_04}= #{effectiveStatus,jdbcType=VARCHAR} group by rp.pledge_finprod_id, fp.finprod_market_id, fp.finprod_abbr, rp.portfolio_id, pp.portfolio_name, rp.pledge_ratio, mbvi.NETPRICE, fp.REGIST_ORG, T8.DIS_FACE_VALUE

select * from (select aaa.* from (
UNION ALL
) aaa left join SYS_DATADICT_LIST sdlStatus on aaa.effectiveStatus=sdlStatus.ITEM_CODE and sdlStatus.DICT_CODE='STATUS_VALID' left join SYS_DATADICT_LIST sdlbjStatus on aaa.quotationState=sdlbjStatus.ITEM_CODE and sdlbjStatus.DICT_CODE='DEAL_TYPE_IBU' left join SYS_DATADICT_LIST sdlfsStatus on aaa.sendStatus=sdlfsStatus.ITEM_CODE and sdlfsStatus.DICT_CODE='SEND_TYPE_IBU' left join SYS_DATADICT_LIST sdlrole on aaa.quoteRoleType=sdlrole.ITEM_CODE and sdlrole.DICT_CODE='QUOTE_ROLE_TYPE' left join SYS_DATADICT_LIST sdl on aaa.finprodType2=sdl.ITEM_CODE and sdl.DICT_CODE='REG_ASSET_TYPE' left join SYS_DATADICT_LIST dictps on aaa.PS=dictps.ITEM_CODE and dictps.DICT_CODE='PS' left join SYS_DATADICT_LIST dictquote on aaa.quoteType=dictquote.ITEM_CODE and dictquote.DICT_CODE='QUOTE_TYPE' left join SYS_DATADICT_LIST dictsp on aaa.settleSpeed=dictsp.ITEM_CODE and dictsp.DICT_CODE='ACCOUNT_SPEED'
order by aaa.finprodType2, aaa.quotationState,aaa.ps DESC)
order by ${sort} ${direction}

mapper.sql:
select decode(ib.trade_status,'15',#{STATUS_VALID_03},#{STATUS_VALID_01}) as effectiveStatus, case when ib.trade_status in ('07','06','08','15','13') then #{DEAL_TYPE_IBU_02} else #{DEAL_TYPE_IBU_01} end as quotationState, ib.send_status as sendStatus, ib.quote_role_type as quoteRoleType, ib.ps as ps, #{REG_ASSET_TYPE_01} as finprodType2, ib.finprod_id as finprodId, fp.finprod_market_id as finprodMarketId, fp.finprod_abbr as finprodAbbr, ib.quote_type as quoteType, ib.ou_party_id as traderid, mccit.PARTY_ABBR as traderidStr, nvl(su1.TRADER_NAME,ib.ou_trader_id) as trader, ibd.cp_party_id as counterId, ibd.PARTY_ABBR as counterIdStr, ibd.cp_trader as counterTrader, decode(ib.settle_speed,0,'01',1,'02',2,'03') as settleSpeed, ib.sec_manage_acct_id as secManageAcctId, stlinfo.sec_acct_name as secManageAcctIdStr, ib.share_amt/100 as faceValue, ibd.tradeYield as tradeYield, null as termDays, ib.fprice_amt as tradeAmt, ib.quote_id as quoteId, ibd.execid as execid, deal.portfolioId as portfolioIds, deal.portfolioName as portfolioNames, deal.entrustId as entrustId, to_char(ib.quote_date,'yyyy-MM-dd') as quoteDate, to_char(total.trade_date,'yyyy-MM-dd') as tradeDate, ib.remark, ibd.calMode as calMode from ibu_quote_bond ib left join fin_product fp on ib.finprod_id=fp.finprod_id left join ( select ibd.quote_id,ibd.cp_party_id as cp_party_id,mccic.PARTY_ABBR as PARTY_ABBR, nvl(su.TRADER_NAME,ibd.cp_trader) cp_trader,ibd.execid, decode(ibd.CALCULATE_FIELD,'01',TO_CHAR(ROUND(ibd.unit_cprice,4),'FM990.0000'), '02',TO_CHAR(ROUND(ibd.yield*100,4),'FM990.0000') ||'%', '03',TO_CHAR(ROUND(ibd.exer_yield*100,4),'FM990.0000')||'%') as tradeYield, ibd.CALCULATE_FIELD as calMode from ibu_quote_bond_det ibd inner join ibu_quote_bond t1 on ibd.quote_id=t1.quote_id and t1.quote_type='01' LEFT JOIN MST_CFETS_CUSTOMER_INFO mccic ON ibd.cp_party_id= mccic.party_id left join MST_CFETS_CUSTOMER_TRADER su on ibd.cp_trader=su.TRADER_ID
union all select ibd.quote_id,wm_concat(ibd.cp_party_id) as cp_party_id,wm_concat(mccic.PARTY_ABBR) as PARTY_ABBR, wm_concat(nvl(su.TRADER_NAME,ibd.cp_trader)) cp_trader, ibd.execid,null as tradeYield,null as calMode from ibu_quote_bond_det ibd inner join ibu_quote_bond t1 on ibd.quote_id=t1.quote_id and t1.quote_type='02' and t1.trade_status!='07' LEFT JOIN MST_CFETS_CUSTOMER_INFO mccic ON ibd.cp_party_id= mccic.party_id left join MST_CFETS_CUSTOMER_TRADER su on ibd.cp_trader=su.TRADER_ID group by ibd.quote_id,ibd.execid
union all select ibd.quote_id,ibd.cp_party_id as cp_party_id,mccic.PARTY_ABBR as PARTY_ABBR, nvl(su.TRADER_NAME,ibd.cp_trader) cp_trader,ibd.execid, TO_CHAR(ROUND(ibd.yield*100,4),'FM990.0000') ||'%' as tradeYield, ibd.CALCULATE_FIELD as calMode from ibu_quote_bond_det ibd inner join ibu_quote_bond t1 on ibd.quote_id=t1.quote_id and t1.quote_type='02' and t1.trade_status='07' LEFT JOIN MST_CFETS_CUSTOMER_INFO mccic ON ibd.cp_party_id= mccic.party_id left join MST_CFETS_CUSTOMER_TRADER su on ibd.cp_trader=su.TRADER_ID where ibd.trade_status='07' )ibd on ib.quote_id=ibd.quote_id inner join( select ir.quote_id,wm_concat(ir.portfolio_id) as portfolioId,wm_concat(pp.portfolio_name) portfolioName, wm_concat(distinct ir.entrust_id) as entrustId from ibu_quote_etr_re ir left join ptl_portfolio pp on ir.portfolio_id=pp.portfolio_id
inner JOIN PTL_PORTFOLIO_AUTHORITY PPA ON ir.portfolio_id = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userId}
where 1=1
AND ir.portfolio_id in
#{item}
AND ir.entrust_id like '%' || #{entrustId,jdbcType=VARCHAR} || '%'
group by ir.quote_id)deal on ib.quote_id=deal.quote_id left join trdquto_match_info match on ib.quote_id=match.pre_trade_id left join trd_fin_product_deal_total total on match.trd_id=total.totle_trade_id left join stl_sec_acct_info stlinfo on ib.sec_manage_acct_id=stlinfo.sec_acct_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mccit ON ib.ou_party_id= mccit.party_id left join MST_CFETS_CUSTOMER_TRADER su1 on ib.ou_trader_id=su1.TRADER_ID where 1=1
AND ib.quote_date= #{sysDate,jdbcType=DATE}
AND ib.quote_date>= #{startDate,jdbcType=DATE}
AND ib.quote_date<=#{endDate,jdbcType=DATE}
and ib.create_user= #{submitUserId}
AND ib.ps=#{ps}
AND #{REG_ASSET_TYPE_01}=#{regAssetType}
AND ib.finprod_id in
#{item}
AND ib.settle_speed = #{settleSpeed,jdbcType=VARCHAR}
AND ib.sec_manage_acct_id in
#{item}
AND ib.quote_Id like CONCAT('%',CONCAT(#{quoteId,jdbcType=VARCHAR},'%'))
AND decode(ib.trade_status,'15',#{STATUS_VALID_03},#{STATUS_VALID_01})=#{effectiveStatus,jdbcType=VARCHAR}
AND ib.quote_type= #{quoteType,jdbcType=VARCHAR}
AND ibd.cp_party_id like '%' || #{counterId,jdbcType=VARCHAR} || '%'
union all
select decode(ic.trade_status,'15',#{STATUS_VALID_03},#{STATUS_VALID_01}) as effectiveStatus, case when ic.trade_status in ('07','06','08','15','13') then #{DEAL_TYPE_IBU_02} else #{DEAL_TYPE_IBU_01} end as quotationState, ic.send_status as sendStatus, ic.quote_role_type as quoteRoleType, ic.repo_ps as ps, #{REG_ASSET_TYPE_02} as finprodType2, ic.term_type as finprodId, ic.term_type as finprodMarketId, null as finprodAbbr, ic.quote_type as quoteType, ic.ou_party_id as traderid, mccit.PARTY_ABBR as traderidStr, nvl(su1.TRADER_NAME,ic.ou_trader_id) as trader, ic.cp_party_id as counterId, mccic.PARTY_ABBR as counterIdStr, nvl(su2.TRADER_NAME,ic.cp_trader_id) as counterTrader, decode(ic.settle_speed,0,'01',1,'02',2,'03') as settleSpeed, ic.sec_manage_acct_id as secManageAcctId, stlinfo.sec_acct_name as secManageAcctIdStr, null as faceValue, TO_CHAR(ROUND(ic.rate*100,4),'FM990.0000') ||'%' as tradeYield, ic.term as termDays, ic.fprice_amt as tradeAmt, ic.quote_id as quoteId, ic.execid as execid, deal.portfolioId as portfolioIds, deal.portfolioName as portfolioNames, deal.entrustId as entrustId, to_char(ic.quote_date,'yyyy-MM-dd') as quoteDate, to_char(total.trade_date,'yyyy-MM-dd') as tradeDate, ic.remark, null as calMode from ibu_quote_crep ic inner join( select ir.quote_id,wm_concat(ir.portfolio_id) as portfolioId,wm_concat(pp.portfolio_name) portfolioName, wm_concat(distinct ir.entrust_id) as entrustId from ibu_quote_etr_re ir left join ptl_portfolio pp on ir.portfolio_id=pp.portfolio_id
inner JOIN PTL_PORTFOLIO_AUTHORITY PPA ON ir.portfolio_id = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userId}
where 1=1
AND ir.portfolio_id in
#{item}
AND ir.entrust_id like '%' || #{entrustId,jdbcType=VARCHAR} || '%'
group by ir.quote_id)deal on ic.quote_id=deal.quote_id left join trdquto_match_info match on ic.quote_id=match.pre_trade_id left join trd_fin_product_deal_total total on match.trd_id=total.totle_trade_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mccit ON ic.ou_party_id= mccit.party_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mccic ON ic.cp_party_id= mccic.party_id left join MST_CFETS_CUSTOMER_TRADER su1 on ic.ou_trader_id=su1.TRADER_ID left join MST_CFETS_CUSTOMER_TRADER su2 on ic.cp_trader_id=su2.TRADER_ID left join stl_sec_acct_info stlinfo on ic.sec_manage_acct_id=stlinfo.sec_acct_id
where 1=1
AND ic.quote_date= #{sysDate,jdbcType=DATE}
AND ic.quote_date>= #{startDate,jdbcType=DATE}
AND ic.quote_date<=#{endDate,jdbcType=DATE}
and (ic.create_user= #{submitUserId} or ic.update_user= #{submitUserId})
AND ic.repo_ps=#{ps}
AND #{REG_ASSET_TYPE_02}=#{regAssetType}
AND ic.term_type in
#{item}
AND ic.settle_speed = #{settleSpeed,jdbcType=VARCHAR}
AND ic.sec_manage_acct_id in
#{item}
AND ic.quote_Id like CONCAT('%',CONCAT(#{quoteId,jdbcType=VARCHAR},'%'))
AND decode(ic.trade_status,'15',#{STATUS_VALID_03},#{STATUS_VALID_01})=#{effectiveStatus,jdbcType=VARCHAR}
AND ic.quote_type= #{quoteType,jdbcType=VARCHAR}
AND ic.cp_party_id like '%' || #{counterId,jdbcType=VARCHAR} || '%'

