inner join ibu_quote_bond ib on ir.quote_id=ib.quote_id LEFT JOIN ETR_ENTRUST ee ON ir.entrust_id = ee.entrust_id LEFT JOIN ( select t.entrust_id, sum(t.ent_finish_amt) as ent_finish_amt from ETR_FINISH_STATUS t group by t.entrust_id )efs ON ee.Entrust_Id = efs.entrust_id left join stl_sec_acct_info stlinfo on ib.sec_manage_acct_id=stlinfo.sec_acct_id left join ( select ibd.quote_id,ibd.cp_party_id as cp_party_id,mccic.PARTY_ABBR as PARTY_ABBR, nvl(su.TRADER_NAME,ibd.cp_trader) cp_trader,ibd.yield as yield, ibd.unit_cprice, ibd.exer_yield, ibd.unit_int, ibd.unit_fprice, ibd.cprice_amt, ibd.int_amt, ibd.fprice_amt from ibu_quote_bond_det ibd inner join ibu_quote_bond t1 on ibd.quote_id=t1.quote_id and t1.quote_type='01' LEFT JOIN MST_CFETS_CUSTOMER_INFO mccic ON ibd.cp_party_id= mccic.party_id left join MST_CFETS_CUSTOMER_TRADER su on ibd.cp_trader=su.TRADER_ID where ibd.quote_id= #{quoteId,jdbcType=VARCHAR}
union all
select ibd.quote_id,wm_concat(ibd.cp_party_id) as cp_party_id,wm_concat(mccic.PARTY_ABBR) as PARTY_ABBR, wm_concat(nvl(su.TRADER_NAME,ibd.cp_trader)) cp_trader, null as yield, null as unit_cprice, null as exer_yield, null as unit_int, null as unit_fprice, null as cprice_amt, null as int_amt, null as fprice_amt from ibu_quote_bond_det ibd inner join ibu_quote_bond t1 on ibd.quote_id=t1.quote_id and t1.quote_type='02' and t1.trade_status!='07' and ibd.quote_id= #{quoteId,jdbcType=VARCHAR} LEFT JOIN MST_CFETS_CUSTOMER_INFO mccic ON ibd.cp_party_id= mccic.party_id left join MST_CFETS_CUSTOMER_TRADER su on ibd.cp_trader=su.TRADER_ID group by ibd.quote_id union all select ibd.quote_id,ibd.cp_party_id as cp_party_id,mccic.PARTY_ABBR as PARTY_ABBR, nvl(su.TRADER_NAME,ibd.cp_trader) cp_trader, ibd.yield as yield, ibd.unit_cprice, ibd.exer_yield, ibd.unit_int, ibd.unit_fprice, ibd.cprice_amt, ibd.int_amt, ibd.fprice_amt from ibu_quote_bond_det ibd inner join ibu_quote_bond t1 on ibd.quote_id=t1.quote_id and t1.quote_type='02' and t1.trade_status='07' LEFT JOIN MST_CFETS_CUSTOMER_INFO mccic ON ibd.cp_party_id= mccic.party_id left join MST_CFETS_CUSTOMER_TRADER su on ibd.cp_trader=su.TRADER_ID where ibd.trade_status='07' and ibd.quote_id= #{quoteId,jdbcType=VARCHAR} )ibd on ir.quote_id=ibd.quote_id where ir.quote_id=#{quoteId,jdbcType=VARCHAR} and decode(ib.trade_status,'15',#{STATUS_VALID_03},#{STATUS_VALID_01})= #{effectiveStatus,jdbcType=VARCHAR} union all select ir.entrust_id as entrustId, ir.portfolio_id as portfolioId, pp.portfolio_name as portfolioName, (nvl(ee.entrust_amt,0) - nvl(efs.ent_finish_amt,0))/10000 unFinshAmt, ir.share_amt/100 as faceValue, ir.DEAL_FEE_AMT as trdFeeAmt, ir.SETT_FEE_AMT as settleFeeAmt, nvl(ir.cprice_amt,ir.share_amt*ibd.unit_cprice) as cpriceAmt, nvl(ir.int_amt,ir.fprice_amt-(ir.share_amt*ibd.unit_cprice)) as intAmt, ir.fprice_amt as fpriceAmt, EE.PRICE_MODEL as priceModel, EE.BUSINESS_MODEL as businessModel, ib.sec_manage_acct_id as secManageAcctId, stlinfo.sec_acct_name as secManageAcctIdStr, ibd.unit_cprice as unitCprice, ibd.yield*100 as yield, ibd.exer_yield*100 as exerYield from wfl_ibu_quote_etr_re ir left join ptl_portfolio pp on ir.portfolio_id=pp.portfolio_id
inner JOIN PTL_PORTFOLIO_AUTHORITY PPA ON ir.portfolio_id = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userId}
inner join wfl_ibu_quote_bond2 ib on ir.quote_id=ib.quote_id LEFT JOIN ETR_ENTRUST ee ON ir.entrust_id = ee.entrust_id LEFT JOIN ( select t.entrust_id, sum(t.ent_finish_amt) as ent_finish_amt from ETR_FINISH_STATUS t group by t.entrust_id )efs ON ee.Entrust_Id = efs.entrust_id left join stl_sec_acct_info stlinfo on ib.sec_manage_acct_id=stlinfo.sec_acct_id left join ( select ibd.quote_id,ibd.cp_party_id as cp_party_id,mccic.PARTY_ABBR as PARTY_ABBR, nvl(su.TRADER_NAME,ibd.cp_trader) cp_trader,ibd.yield as yield, ibd.unit_cprice, ibd.exer_yield, ibd.unit_int, ibd.unit_fprice, ibd.cprice_amt, ibd.int_amt, ibd.fprice_amt from ibu_quote_bond_det ibd inner join ibu_quote_bond t1 on ibd.quote_id=t1.quote_id and t1.quote_type='01' LEFT JOIN MST_CFETS_CUSTOMER_INFO mccic ON ibd.cp_party_id= mccic.party_id left join MST_CFETS_CUSTOMER_TRADER su on ibd.cp_trader=su.TRADER_ID where ibd.quote_id= #{quoteId,jdbcType=VARCHAR}
union all
select ibd.quote_id,wm_concat(ibd.cp_party_id) as cp_party_id,wm_concat(mccic.PARTY_ABBR) as PARTY_ABBR, wm_concat(nvl(su.TRADER_NAME,ibd.cp_trader)) cp_trader, null as yield, null as unit_cprice, null as exer_yield, null as unit_int, null as unit_fprice, null as cprice_amt, null as int_amt, null as fprice_amt from ibu_quote_bond_det ibd inner join ibu_quote_bond t1 on ibd.quote_id=t1.quote_id and t1.quote_type='02' and t1.trade_status!='07' and ibd.quote_id= #{quoteId,jdbcType=VARCHAR} LEFT JOIN MST_CFETS_CUSTOMER_INFO mccic ON ibd.cp_party_id= mccic.party_id left join MST_CFETS_CUSTOMER_TRADER su on ibd.cp_trader=su.TRADER_ID group by ibd.quote_id union all select ibd.quote_id,ibd.cp_party_id as cp_party_id,mccic.PARTY_ABBR as PARTY_ABBR, nvl(su.TRADER_NAME,ibd.cp_trader) cp_trader, ibd.yield as yield, ibd.unit_cprice, ibd.exer_yield, ibd.unit_int, ibd.unit_fprice, ibd.cprice_amt, ibd.int_amt, ibd.fprice_amt from ibu_quote_bond_det ibd inner join ibu_quote_bond t1 on ibd.quote_id=t1.quote_id and t1.quote_type='02' and t1.trade_status='07' LEFT JOIN MST_CFETS_CUSTOMER_INFO mccic ON ibd.cp_party_id= mccic.party_id left join MST_CFETS_CUSTOMER_TRADER su on ibd.cp_trader=su.TRADER_ID where ibd.trade_status='07' and ibd.quote_id= #{quoteId,jdbcType=VARCHAR} )ibd on ir.quote_id=ibd.quote_id where ir.quote_id=#{quoteId,jdbcType=VARCHAR} and #{STATUS_VALID_04}= #{effectiveStatus,jdbcType=VARCHAR}

select ir.entrust_id as entrustId, ir.portfolio_id as portfolioId, pp.portfolio_name as portfolioName, ir.fprice_amt as tradeAmt, ir.DEAL_FEE_AMT as trdFeeAmt, ir.SETT_FEE_AMT as settleFeeAmt, ir.int_amt as intAmt, ir.m_trade_amt as mtradeAmt, ir.share_ct_amt as disFaceValue, EE.PRICE_MODEL as priceModel, ic.rate*100 tradeYield from ibu_quote_etr_re ir left join ptl_portfolio pp on ir.portfolio_id=pp.portfolio_id
inner JOIN PTL_PORTFOLIO_AUTHORITY PPA ON ir.portfolio_id = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userId}
LEFT JOIN ETR_ENTRUST ee ON ir.entrust_id = ee.entrust_id left join ibu_quote_crep ic on ir.quote_id=ic.quote_id where ir.quote_id=#{quoteId,jdbcType=VARCHAR} and decode(ic.trade_status,'15',#{TRADE_FLOW_STATUS03},#{TRADE_FLOW_STATUS02})= #{effectiveStatus,jdbcType=VARCHAR} union all select ir.entrust_id as entrustId, ir.portfolio_id as portfolioId, pp.portfolio_name as portfolioName, ir.fprice_amt as tradeAmt, ir.DEAL_FEE_AMT as trdFeeAmt, ir.SETT_FEE_AMT as settleFeeAmt, ir.int_amt as intAmt, ir.m_trade_amt as mtradeAmt, ir.share_ct_amt as disFaceValue, EE.PRICE_MODEL as priceModel, ic.rate*100 tradeYield from wfl_ibu_quote_etr_re ir left join ptl_portfolio pp on ir.portfolio_id=pp.portfolio_id
inner JOIN PTL_PORTFOLIO_AUTHORITY PPA ON ir.portfolio_id = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userId}
LEFT JOIN ETR_ENTRUST ee ON ir.entrust_id = ee.entrust_id left join wfl_ibu_quote_crep ic on ir.quote_id=ic.quote_id where ir.quote_id=#{quoteId,jdbcType=VARCHAR} and #{TRADE_FLOW_STATUS01}= #{effectiveStatus,jdbcType=VARCHAR}

select * from (select aaa.* from ( select distinct case when match.match_status is null or match.match_status!='01' then '01' when match.match_status ='01' and (match.trd_conf_status is null or match.trd_conf_status='0') then '02' when match.trd_conf_status='1' then '03' end as matchStatus, I.Execid as execid, I.Businesstype as businesstype, fp.finprod_id as finprodId, decode(I.BUSINESSTYPE,'BOND',ts.SECID,'REPO',tr.secid) as finprodMarketId, decode(I.BUSINESSTYPE,'BOND',fp.finprod_abbr,'REPO',null) as finprodAbbr, nvl(ts.ps,tr.ps) as ps, decode(decode(I.BUSINESSTYPE,'BOND',ts.SETTLE_SPEED,'REPO',tr.SETTLE_SPEED),'1','01','2','02','3','03') settleSpeed, nvl(ts.OURDEPOSITACCOUNTNUMBER,tr.OURDEPOSITACCOUNTNUMBER) as secManageAcctId, stlinfo.sec_acct_name as secManageAcctIdStr, ts.prinamt/10000 as faceValue, decode(I.BUSINESSTYPE, 'BOND', I.yield2*100, 'REPO', I.PRICE*100) tradeYield, I.TRADELIMITDAYS as termDays, decode(I.BUSINESSTYPE, 'BOND', I.SETTLCURRAMT, 'REPO', DECODE(I.MARKETINDICATOR, 9, I.TRADECASHAMT, 10, I.SETTLCURRAMT)) as tradeAmt, I.QUOTEID as quoteid,
I.ourinstitutioncode as traderid,
I.OURINSTITUTIONCHINESEFULLNAME as traderidStr,
I.OURTRADERCHINESENAME trader, I.Counterinstitutioncode as counterId,
I.INSTITUTIONCHINESEFULLNAME as counterIdStr,
decode(I.Clearingmethod,'13','01','6','02') as clearType, to_char(total.trade_date,'yyyy-MM-dd') as tradeDate, nvl(ts.dealtext,tr.dealtext) as remark, '' tenderTarget, '' tgBusiType from INTERF_CSTP_TRADE I INNER JOIN (SELECT EXECID ,MAX(UPDATETIME) UPDATETIME FROM INTERF_CSTP_TRADE GROUP BY EXECID) II ON II.EXECID = I.EXECID AND II.UPDATETIME = I.UPDATETIME left join INTERF_OPICS_TRAD_REPO tr on tr.oritradeid = I.EXECID left join INTERF_TRAD_SECDEAL ts on ts.FEDEALNO = I.EXECID left join fin_product fp on ts.SECID=fp.finprod_market_id and fp.finprod_type='F01' LEFT JOIN SYS_USER_ADD sua ON nvl(ts.TRAD,tr.BUYTRADER) =sua.IBU_TRADER LEFT JOIN SYS_USER su ON sua.USER_ID =su.USER_ID
left join stl_sec_acct_info stlinfo on nvl(ts.OURDEPOSITACCOUNTNUMBER,tr.OURDEPOSITACCOUNTNUMBER)=stlinfo.sec_acct_id
left join trdquto_match_info match on I.EXECID=match.exe_id left join trd_fin_product_deal_total total on match.trd_id=total.totle_trade_id where 1=1
AND nvl(ts.dealdate,tr.dealdate) = #{sysDate,jdbcType=DATE}
AND nvl(ts.dealdate,tr.dealdate)>= #{startDate,jdbcType=DATE}
AND nvl(ts.dealdate,tr.dealdate)<=#{endDate,jdbcType=DATE}
and su.USER_NAME= #{submitUserId}
AND nvl(ts.ps,tr.ps)=#{ps}
AND I.Businesstype=#{regAssetType}
AND (nvl(ts.SECID,tr.SECID) in
#{item}
or ts.SECID in
CONCAT(#{item},'.IB')
or fp.finprod_id in
#{item}
)
and decode(decode(I.BUSINESSTYPE,'BOND',ts.SETTLE_SPEED,'REPO',tr.SETTLE_SPEED),'1','01','2','02','3','03') = #{settleSpeed,jdbcType=VARCHAR}
AND nvl(ts.OURDEPOSITACCOUNTNUMBER,tr.OURDEPOSITACCOUNTNUMBER) in
#{item}
and I.Execid LIKE CONCAT('%',CONCAT(#{execid},'%'))
and I.QUOTEID LIKE CONCAT('%',CONCAT(#{quoteid},'%'))
AND I.ourinstitutioncode IN
#{item}
AND I.Counterinstitutioncode IN
#{item}
AND (case when match.match_status is null or match.match_status!='01' then '01' when match.match_status ='01' and (match.trd_conf_status is null or match.trd_conf_status='0') then '02' when match.trd_conf_status='1' then '03' end) in
#{item}
union all SELECT TMI.MATCH_STATUS matchStatus, ICB.TRD_ID execid, FPT.TYPE_9 businesstype, ICB.INSTRUMENT_ID finprodId, FP.FINPROD_MARKET_ID finprodMarketId, ICB.INSTRUMENT_SHORT_NAME finprodAbbr, #{PS_T01} ps, null AS settleSpeed, '' AS secManageAcctId, '' as secManageAcctIdStr, ICB.SUBSCRIPTION_AMOUNT*10000 faceValue, CASE WHEN FPI.TENDER_TARGET=#{TENDER_TARGET_02} THEN ICB.ISSUE_PRICE WHEN FPI.TENDER_TARGET=#{TENDER_TARGET_01} THEN ICB.COUPON_RATE WHEN FPI.TENDER_TARGET=#{TENDER_TARGET_03} THEN ICB.SPREAD END AS tradeYield, null termDays, ICB.ACTUAL_FEE AS tradeAmt, '' quoteid, ICB.FULL_CHINESE_NAME_OF_SUBSCRIBE traderid, ICB.SUBMIT_USER AS traderidStr, '' trader, '' counterId, '' counterIdStr, '' clearType, to_char(to_date(ICB.SUBSCRIPTION_TIME,'yyyy-MM-dd HH24:mi:ss'),'yyyy-MM-dd') tradeDate, '' remark, FPI.TENDER_TARGET tenderTarget, #{BUSI_TYPE_POSITION_34} tgBusiType FROM INTERF_CSTP_BJFXJG ICB LEFT JOIN FIN_PRODUCT FP ON FP.FINPROD_MARKET_ID = ICB.INSTRUMENT_ID LEFT JOIN FIN_PRODUCT_ISSUE FPI ON FPI.FINPROD_ID = FP.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE FPT ON FPT.FINPROD_ID = FP.FINPROD_ID LEFT JOIN TRDQUTO_MATCH_INFO TMI ON TMI.EXE_ID = ICB.TRD_ID WHERE FP.TRADE_MARKET IN (#{TRADE_PLACE_01},#{TRADE_PLACE_02})
AND to_date(to_char(to_date(ICB.SUBSCRIPTION_TIME,'yyyy-MM-dd HH24:mi:ss'),'yyyy-MM-dd'),'yyyy-MM-dd') = #{sysDate,jdbcType=DATE}
AND to_date(to_char(to_date(ICB.SUBSCRIPTION_TIME,'yyyy-MM-dd HH24:mi:ss'),'yyyy-MM-dd'),'yyyy-MM-dd')>= #{startDate,jdbcType=DATE}
AND to_date(to_char(to_date(ICB.SUBSCRIPTION_TIME,'yyyy-MM-dd HH24:mi:ss'),'yyyy-MM-dd'),'yyyy-MM-dd') <=#{endDate,jdbcType=DATE}
AND #{PS_T01} =#{ps}
AND FPT.TYPE_9 = #{regAssetType}
AND ICB.INSTRUMENT_ID in
#{item}
and 1 !=1
AND 1 !=1
and ICB.TRD_ID LIKE CONCAT('%',CONCAT(#{execid},'%'))
and 1!=1
AND ICB.FULL_CHINESE_NAME_OF_SUBSCRIBE IN
#{item}
AND 1 != 1
AND TMI.MATCH_STATUS in
#{item}
) aaa left join SYS_DATADICT_LIST sdlMatch on aaa.matchStatus=sdlMatch.ITEM_CODE and sdlMatch.DICT_CODE='CSTP_MATCH_STATUS' left join SYS_DATADICT_LIST sdl on aaa.businesstype=sdl.ITEM_CODE and sdl.DICT_CODE='CSTP_BUSINESS_TYPE' left join SYS_DATADICT_LIST dictps on aaa.PS=dictps.ITEM_CODE and dictps.DICT_CODE='PS' left join SYS_DATADICT_LIST dictsp on aaa.settleSpeed=dictsp.ITEM_CODE and dictsp.DICT_CODE='ACCOUNT_SPEED' left join SYS_DATADICT_LIST dictct on aaa.clearType=dictct.ITEM_CODE and dictct.DICT_CODE='CLEAR_TYPE'
order by aaa.businesstype, aaa.matchStatus,aaa.ps DESC)
order by ${sort} ${direction}

if.where:
((
sdlMatch.ITEM_VALUE || '|' ||aaa.execid || '|' || sdl.ITEM_VALUE || '|' || aaa.finprodMarketId || '|' || aaa.finprodAbbr
|| '|' || dictps.ITEM_VALUE || '|' || dictsp.ITEM_VALUE
|| '|' || aaa.secManageAcctIdStr   || '|' || aaa.quoteid
|| '|' || aaa.traderidStr   || '|' || aaa.trader
|| '|' || aaa.counterIdStr   || '|' || dictct.ITEM_VALUE || '|' || aaa.remark
like '%' || #{search} || '%')
or to_char(aaa.faceValue,'FM9999999999999990.90')=#{search} or to_char(aaa.faceValue)=#{search}
or to_char(aaa.tradeYield,'FM99990.9990')=#{search} or  aaa.tradeYield||'' =#{search}
or aaa.termDays||'' =#{search}
or to_char(aaa.tradeAmt,'FM9999999999999990.90')=#{search} or to_char(aaa.tradeAmt)=#{search}
or aaa.tradeDate||'' =#{search}
or aaa.tradeDate||''=#{year}||'-'||#{search}
or replace(aaa.tradeDate,'-','/')||''=#{search}
or replace(aaa.tradeDate,'-','/')||''=#{year}||'/'||#{search}
)

mapper.select:
select * from (SELECT aaa.* FROM( SELECT distinct decode(T1.is_cancel,'N',#{STATUS_VALID_01},'Y',#{STATUS_VALID_03}) as effectiveStatus, case when T9.PS = #{feePs02} and T9.SETTLE_STATUS = #{settlementStatus01} and T9.ORDER_RET_STATUS = #{commandDealStatus01} THEN #{cleanStatus01} when T9.PS = #{feePs02} and T9.SETTLE_STATUS = #{settlementStatus01} and T9.ORDER_RET_STATUS = #{commandDealStatus02} THEN #{cleanStatus02} when T9.PS = #{feePs02} and (T9.SETTLE_STATUS is null or T9.SETTLE_STATUS = #{settlementStatus02}) and T9.ORDER_RET_STATUS = '03' THEN #{cleanStatus03} ELSE NULL END cleanStatus, decode(T1.finprod_type2,'F03',null,nvl(T8.SETTLE_STATUS,#{DELIVERY_STATUS_01})) settleStatus, T1.TOTLE_TRADE_ID totleTradeId, T1.FINPROD_TYPE2 finprodType2, sdl1.item_value finprodType2Str, btm.BUSI_TYPE tgBusiType, sdl2.item_value tgBusiTypeStr, t2.FINPROD_ID AS finprodId, nvl(T2.FINPROD_MARKET_ID,T3.TERM_TYPE) finprodMarketId, T2.FINPROD_ABBR finprodAbbr, T1.PS ps, sdl3.item_value psStr, T1.TRADE_MARKET tradeMarket, sdl4.item_value tradeMarketStr, T1.TRADE_MARKET_MODE tradeMarketMode, sdl6.item_value tradeMarketModeStr, T1.settle_speed as settleSpeed, 'T+'||T1.settle_speed as settleSpeedStr, T1.SEC_MANAGE_ACCT_ID as secManageAcctId, T7.SEC_ACCT_NAME secManageAcctIdStr, decode(T1.finprod_type2,'F01',deal.share_amt/100,null)as faceValue, case when T1.finprod_type2='F01' then decode(nvl(regAdd.CAL_MODE,ibuDet.CALCULATE_FIELD),'01',TO_CHAR(ROUND(T1.unit_cprice,4),'FM990.0000'), '02',TO_CHAR(ROUND(T1.yield*100,4),'FM990.0000') ||'%', '03',TO_CHAR(ROUND(T1.exer_yield*100,4),'FM990.0000')||'%', TO_CHAR(ROUND(T1.yield*100,4),'FM990.0000') ||'%') when T1.finprod_type2 in ('F02','F03') then TO_CHAR(ROUND(T1.rate*100,4),'FM990.0000') ||'%' else null end as tradeYield, T3.term as termDays, deal.trade_Amt tradeAmt, T1.ccy as ccy, sdl7.item_value as ccyStr, to_char(T1.TRADE_DATE,'yyyy-MM-dd') as confirmTradeDate, to_char(T1.SETTLE_DATE,'yyyy-MM-dd') as settleDate, match.exe_id as execid, T1.counter_id as counterId, T6.counter_name counterIdStr, T1.remark, T1.TRADE_DATE as tradeDate, nvl(regAdd.CAL_MODE,ibuDet.CALCULATE_FIELD) as calMode, match.pre_trade_id preTradeId, match.match_status as matchStatus, T1.trader as trader, '' bidId, '' bidModle FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 inner join ( select td.totle_trade_id,sum(td.share_amt) share_amt, sum(td.trade_amt) as trade_Amt from trd_product_deal td left join trd_product_deal_add tda on td.trade_id=tda.trade_id
inner JOIN PTL_PORTFOLIO_AUTHORITY PPA ON tda.portfolio_id = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userId}
where td.trade_status='01' group by td.totle_trade_id )deal on T1.totle_trade_id=deal.totle_trade_id left join trd_product_deal trd_product_deal on T1.totle_trade_id = trd_product_deal.totle_trade_id LEFT JOIN FIN_PRODUCT T2 ON T1.FINPROD_ID = T2.FINPROD_ID left join fin_trade_product T3 on trd_product_deal.FINPROD_ID=T3.finprod_id left join FIN_PRODUCT_TYPE FIN_PRODUCT_TYPE on FIN_PRODUCT_TYPE.FINPROD_ID=trd_product_deal.FINPROD_ID LEFT JOIN MST_COUNTER_PARTY T6 ON T1.COUNTER_ID = T6.counter_id LEFT JOIN STL_SEC_ACCT_INFO T7 ON T1.SEC_MANAGE_ACCT_ID = T7.SEC_ACCT_ID LEFT JOIN TRD_BANK_MANUAL_SETTLE_INFO T8 ON T1.TOTLE_TRADE_ID = T8.TRADE_ID LEFT JOIN STL_PAY_ORDERS T9 ON T1.TOTLE_TRADE_ID = T9.TRADE_ID left join trdquto_match_info match on T1.totle_trade_id=match.trd_id LEFT JOIN (select INPUT_VALUE_1 as Finprod_Type_Tg,INPUT_VALUE_2 as ps,OUTPUT_VALUE_1 as busi_type from FIN_PRODUCT_TYPE_CONFIG where CONFIG_TYPE='BUSI_TYPE_MAPPING') btm ON FIN_PRODUCT_TYPE.TYPE_8 = btm.Finprod_Type_Tg AND T1.Ps = btm.ps LEFT JOIN SYS_DATADICT_LIST sdl1 on sdl1.dict_code ='PINAN_ASSET_TYPE' and sdl1.item_code = FIN_PRODUCT_TYPE.TYPE_8 LEFT JOIN SYS_DATADICT_LIST sdl2 on sdl2.dict_code ='BUSI_TYPE_POSITION' and sdl2.item_code = btm.BUSI_TYPE LEFT JOIN SYS_DATADICT_LIST sdl3 on sdl3.dict_code ='PS' and sdl3.item_code = T1.PS LEFT JOIN SYS_DATADICT_LIST sdl4 on sdl4.dict_code ='TRADE_PLACE' and sdl4.item_code = T1.TRADE_MARKET LEFT JOIN SYS_DATADICT_LIST sdl6 on sdl6.dict_code ='SHARES_TRADE_MARKET' and sdl6.item_code = T1.TRADE_MARKET_MODE LEFT JOIN SYS_DATADICT_LIST sdl7 on sdl7.dict_code ='CCY' and sdl7.item_code = T1.ccy left join reg_fin_product_deal_total_add regAdd on regAdd.totle_trade_id=nvl(match.PRE_TRADE_ID,T1.B_TRADE_ID) left join ibu_quote_bond_det ibuDet on ibuDet.QUOTE_ID=nvl(match.PRE_TRADE_ID,T1.B_TRADE_ID) and ibuDet.TRADE_STATUS='07' WHERE T1.trade_status='01' and T1.FINPROD_TYPE2 in ('F01','F02','F03') and T1.ps in ('T01','T02','T03','03','04') and T8.SETTLE_STATUS in ('02','04') /*已交收在下面一段中已查询,此处再查询会导致查询重复*/ AND T1.trade_date >= #{startDate} AND T1.trade_date <= #{endDate}
and (T1.create_user= #{submitUserId} or T1.update_user= #{submitUserId})
AND nvl(T3.TERM_TYPE,T1.FINPROD_ID) in
#{item}
AND btm.BUSI_TYPE = #{busiType}
AND T1.TOTLE_TRADE_ID LIKE CONCAT('%',CONCAT(#{totleTradeId},'%'))
AND match.exe_id LIKE CONCAT('%',CONCAT(#{execId},'%'))
AND T1.finprod_type2 in
#{item}
AND T1.TRADE_MARKET = #{tradeMarket}
