ASS_02},#{ISSUE_CLASS_03}) THEN T6.COUNTER_NAME WHEN FPI.ISSUE_CLASS = #{ISSUE_CLASS_01} THEN '' END counterIdStr, TFPDT.REMARK AS remark, TFPDT.TRADE_DATE tradeDate, '' calMode, '' preTradeId, '' matchStatus, '' trader, CASE WHEN FPI.ISSUE_CLASS IN(#{ISSUE_CLASS_02},#{ISSUE_CLASS_03}) THEN BO.BID_ID WHEN FPI.ISSUE_CLASS = #{ISSUE_CLASS_01} THEN '' END bidId, BO.BID_MODLE bidModle FROM TRD_FIN_PRODUCT_DEAL_TOTAL TFPDT LEFT JOIN FIN_PRODUCT FP ON FP.FINPROD_ID = TFPDT.FINPROD_ID LEFT JOIN FIN_PRODUCT_ISSUE FPI ON FPI.FINPROD_ID = FP.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE FPT ON FPT.FINPROD_ID = FP.FINPROD_ID LEFT JOIN BID_RESULT_TOTAL BRT ON BRT.TOTAL_WIN_ID = TFPDT.B_TRADE_ID AND BRT.STATUS = #{STATUS_VALID_01} LEFT JOIN TRDQUTO_MATCH_INFO TMI ON TMI.TRD_ID = TFPDT.TOTLE_TRADE_ID LEFT JOIN BID_ORDER BO ON BO.TRADE_STATUS = #{TRADE_STATUS_01} AND BO.IS_CANCEL = 'N' AND (BO.BID_ID=TFPDT.B_TRADE_ID OR BO.BID_ID=BRT.BID_ID OR BO.BID_ID=TMI.PRE_TRADE_ID) LEFT JOIN TRD_MANUAL_SETTLE_INFO TMSI ON TMSI.TRADE_ID = TFPDT.TOTLE_TRADE_ID LEFT JOIN STL_ORDERS SO ON SO.TRADE_ID = TFPDT.TOTLE_TRADE_ID LEFT JOIN SYS_DATADICT_LIST sdl1 on sdl1.dict_code ='PINAN_ASSET_TYPE' and sdl1.item_code = FPT.TYPE_8 LEFT JOIN SYS_DATADICT_LIST sdl4 on sdl4.dict_code ='TRADE_PLACE' and sdl4.item_code = FP.TRADE_MARKET LEFT JOIN SYS_DATADICT_LIST sdl6 on sdl6.dict_code ='SHARES_TRADE_MARKET' and sdl6.item_code = TFPDT.TRADE_MARKET_MODE LEFT JOIN SYS_DATADICT_LIST sdl7 on sdl7.dict_code ='CCY' and sdl7.item_code = TFPDT.ccy LEFT JOIN MST_COUNTER_PARTY T6 ON TFPDT.COUNTER_ID = T6.COUNTER_ID LEFT JOIN STL_SEC_ACCT_INFO T7 ON TFPDT.SEC_MANAGE_ACCT_ID = T7.SEC_ACCT_ID WHERE TFPDT.TRADE_STATUS = #{TRADE_STATUS_01} AND TFPDT.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F32} AND FP.TRADE_MARKET IN (#{TRADE_PLACE_01},#{TRADE_PLACE_02}) AND (BO.BID_ID IS NOT NULL OR BRT.TOTAL_WIN_ID IS NOT NULL OR TMI.PRE_TRADE_ID IS NOT NULL) AND TFPDT.TRADE_DATE >= #{startDate} AND TFPDT.TRADE_DATE <= #{endDate}
