 #{ISSUE_CLASS_01} THEN '' END counterId, CASE WHEN FPI.ISSUE_CLASS IN(#{ISSUE_CLASS_02},#{ISSUE_CLASS_03}) THEN T6.COUNTER_NAME WHEN FPI.ISSUE_CLASS = #{ISSUE_CLASS_01} THEN '' END counterIdStr, TFPDT.REMARK remark, '' calMode, CASE WHEN FPI.ISSUE_CLASS IN(#{ISSUE_CLASS_02},#{ISSUE_CLASS_03}) THEN BO.BID_ID WHEN FPI.ISSUE_CLASS = #{ISSUE_CLASS_01} THEN '' END bidId, BO.BID_MODLE bidModle FROM TRD_PRODUCT_DEAL TPD LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TFPDT ON TFPDT.TOTLE_TRADE_ID = TPD.TOTLE_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD TPDA ON TPDA.TRADE_ID = TPD.TRADE_ID LEFT JOIN PTL_PORTFOLIO PP ON TPDA.PORTFOLIO_ID=PP.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT FP ON FP.FINPROD_ID = TPD.FINPROD_ID LEFT JOIN FIN_PRODUCT_ISSUE FPI ON FPI.FINPROD_ID = FP.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE FPT ON FPT.FINPROD_ID = FP.FINPROD_ID LEFT JOIN BID_RESULT_TOTAL BRT ON BRT.TOTAL_WIN_ID = TFPDT.B_TRADE_ID AND BRT.STATUS = #{STATUS_VALID_01} LEFT JOIN TRDQUTO_MATCH_INFO TMI ON TMI.TRD_ID = TFPDT.TOTLE_TRADE_ID LEFT JOIN BID_ORDER BO ON BO.TRADE_STATUS = #{TRADE_STATUS_01} AND BO.IS_CANCEL = 'N' AND (BO.BID_ID=TFPDT.B_TRADE_ID OR BO.BID_ID=BRT.BID_ID OR BO.BID_ID=TMI.PRE_TRADE_ID) LEFT JOIN TRD_MANUAL_SETTLE_INFO TMSI ON TMSI.TRADE_ID = TFPDT.TOTLE_TRADE_ID LEFT JOIN STL_ORDERS SO ON SO.TRADE_ID = TFPDT.TOTLE_TRADE_ID LEFT JOIN SYS_DATADICT_LIST sdl1 on sdl1.dict_code ='PINAN_ASSET_TYPE' and sdl1.item_code = FPT.TYPE_8 LEFT JOIN SYS_DATADICT_LIST sdl3 on sdl3.dict_code ='PS' and sdl3.item_code = TPD.PS LEFT JOIN SYS_DATADICT_LIST sdl4 on sdl4.dict_code ='TRADE_PLACE' and sdl4.item_code = TPD.TRADE_MARKET LEFT JOIN SYS_DATADICT_LIST sdl6 on sdl6.dict_code ='SHARES_TRADE_MARKET' and sdl6.item_code = TPD.TRADE_MARKET_MODE LEFT JOIN SYS_DATADICT_LIST sdl7 on sdl7.dict_code ='CCY' and sdl7.item_code = TPD.ccy LEFT JOIN MST_COUNTER_PARTY T6 ON TPD.COUNTER_ID = T6.counter_id LEFT JOIN STL_SEC_ACCT_INFO T7 ON TPD.SEC_MANAGE_ACCT_ID = T7.SEC_ACCT_ID WHERE TFPDT.TRADE_STATUS = #{TRADE_STATUS_01} AND TFPDT.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F32} AND FP.TRADE_MARKET IN (#{TRADE_PLACE_01},#{TRADE_PLACE_02}) AND TPD.trade_date >= #{startDate} AND TPD.trade_date <= #{endDate}
and (TPD.create_user= #{submitUserId} or TPD.update_user= #{submitUserId})
AND TPDA.PORTFOLIO_ID in
#{item}
AND FP.FINPROD_ID in
#{item}
AND ( CASE WHEN FPI.ISSUE_CLASS IN(#{ISSUE_CLASS_02},#{ISSUE_CLASS_03}) THEN 'BUSI_TYPE_POSITION_01' WHEN FPI.ISSUE_CLASS = #{ISSUE_CLASS_01} THEN 'BUSI_TYPE_POSITION_34' END ) = #{busiType}
AND TFPDT.TOTLE_TRADE_ID LIKE CONCAT('%',CONCAT(#{totleTradeId},'%'))
AND TPD.trade_id LIKE CONCAT('%',CONCAT(#{busiCode},'%'))
AND (CASE WHEN FPI.ISSUE_CLASS IN(#{ISSUE_CLASS_02},#{ISSUE_CLASS_03}) THEN '' WHEN FPI.ISSUE_CLASS = #{ISSUE_CLASS_01} THEN TMI.EXE_ID END ) LIKE CONCAT('%',CONCAT(#{execId},'%'))
AND TPDA.ENTRUST_ID LIKE CONCAT('%',CONCAT(#{entrustId},'%'))
AND FPT.TYPE_8 in
#{item}
AND TPD.TRADE_MARKET = #{tradeMarket}
AND TPD.TRADE_MARKET_MODE = #{tradeMarketMode}
AND TPD.PS= #{ps}
AND SO.SETTLE_STATUS = #{cleanStatus}
AND TMSI.SETTLE_STATUS= #{settleStatus}
AND (CASE WHEN FPI.ISSUE_CLASS IN(#{ISSUE_CLASS_02},#{ISSUE_CLASS_03}) THEN BO.BID_ID WHEN FPI.ISSUE_CLASS = #{ISSUE_CLASS_01} THEN '' END)!= #{bidId}
AND (decode(TPD.IS_CANCEL,'N',#{STATUS_VALID_01},'Y',#{STATUS_VALID_03})) in
#{item}
)aaa left join SYS_DATADICT_LIST sdles on sdles.DICT_CODE='STATUS_VALID' and aaa.effectiveStatus=sdles.ITEM_CODE left join SYS_DATADICT_LIST sdlcs on sdlcs.DICT_CODE='SETTLE_STATUS' and aaa.cleanStatus=sdlcs.ITEM_CODE left join SYS_DATADICT_LIST sdlss on sdlss.DICT_CODE='DELIVERY_STATUS' and aaa.settleStatus=sdlss.ITEM_CODE
order by aaa.confirmTradeDate,aaa.effectiveStatus,aaa.finprodType2,aaa.tgBusiType,aaa.ps)
order by ${sort} ${direction}

if.where:
((
sdles.ITEM_VALUE || '|' ||sdlcs.ITEM_VALUE || '|' || sdlss.ITEM_VALUE
|| '|' ||aaa.totleTradeId || '|' ||aaa.busiCode  || '|' ||aaa.entrustId
|| '|' || aaa.finprodType2Str   || '|' || aaa.tgBusiTypeStr
|| '|' || aaa.portfolioId   || '|' || aaa.portfolioName
|| '|' || aaa.finprodMarketId || '|' || aaa.finprodAbbr
|| '|' || aaa.psStr|| '|' || aaa.tradeMarketStr|| '|' || aaa.tradeMarketModeStr
|| '|' || aaa.settleSpeedStr  || '|' || aaa.secManageAcctIdStr || '|' || aaa.ccyStr
|| '|' || aaa.execid   || '|' || aaa.counterIdStr || '|' || aaa.remark
like '%' || #{search} || '%')
or to_char(aaa.faceValue,'FM9999999999999990.90')=#{search} or to_char(aaa.faceValue)=#{search}
or aaa.tradeYield=#{search} or  aaa.tradeYield =#{search}||'%'
or aaa.termDays||'' =#{search}
or to_char(aaa.tradeAmt,'FM9999999999999990.90')=#{search} or to_char(aaa.tradeAmt)=#{search}
or aaa.confirmTradeDate||'' =#{search}
or aaa.confirmTradeDate||''=#{year}||'-'||#{search}
or replace(aaa.confirmTradeDate,'-','/')||''=#{search}
or replace(aaa.confirmTradeDate,'-','/')||''=#{year}||'/'||#{search}
or aaa.settleDate||'' =#{search}
or aaa.settleDate||''=#{year}||'-'||#{search}
or replace(aaa.settleDate,'-','/')||''=#{search}
or replace(aaa.settleDate,'-','/')||''=#{year}||'/'||#{search}
)

mapper.select:
SELECT ROWNUM rowNums, TPDA.PORTFOLIO_ID portfolioId, pp.PORTFOLIO_NAME portfolioName, TPD.SHARE_AMT/100 QTYD, TPD.PRIN_AMT prinAmtTheoryd, TPD.INT_AMT intAmtTheoryd, TPD.CPRICE_AMT cpriceAmt, TPD.INT_AMT intAmt, TPD.FPRICE_AMT fpriceAmt, ttft.fee_amt jyFeeAmt, ttft1.fee_amt jsFeeAmt, TPD.TRADE_AMT tradeAmt, TPDA.Entrust_Id entrustId, EE.PRICE_MODEL priceModel, (nvl(ee.entrust_amt,0) - nvl(efs.ent_finish_amt,0))/10000 unFinshAmt, ssai.sec_acct_name secAcctId, TPD.YIELD*100 matureYield, TPD.EXER_YIELD*100 exeYield, EE.BUSINESS_MODEL busiTypePosition, TPD.UNIT_CPRICE unitPrice, ftp.m_int_amt as mintAmt, ftp.m_trade_amt as mtradeAmt, pledges.disFaceValue as disFaceValue, ftp.int_rate*100 as rate FROM TRD_PRODUCT_DEAL TPD INNER JOIN TRD_PRODUCT_DEAL_ADD TPDA on TPD.TRADE_ID = TPDA.TRADE_ID
inner JOIN PTL_PORTFOLIO_AUTHORITY PPA ON TPDA.portfolio_id = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userName}
LEFT JOIN PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = TPDA.PORTFOLIO_ID LEFT JOIN TRD_TRADE_FEE_DETAIL ttft ON tpd.trade_id = ttft.trade_id AND ttft.fee_type =#{feeType06} LEFT JOIN TRD_TRADE_FEE_DETAIL ttft1 ON tpd.trade_id = ttft1.trade_id AND ttft1.fee_type =#{feeType08} LEFT JOIN ETR_ENTRUST ee ON TPDA.Entrust_Id = ee.entrust_id LEFT JOIN ETR_FINISH_STATUS efs ON ee.Entrust_Id = efs.entrust_id AND TPD.TRADE_ID = efs.trade_id LEFT JOIN STL_SEC_ACCT_INFO ssai ON tpd.sec_manage_acct_id = ssai.SEC_ACCT_ID left join fin_trade_product ftp on ftp.finprod_id=TPD.TRADE_ID left join (select pledge.finprod_id,sum(pledge.pledge_number*pledge.pledge_ratio*100) as disFaceValue from FIN_DEAL_PLEDGE pledge group by pledge.finprod_id)pledges on ftp.finprod_id=pledges.finprod_id where TPD.TOTLE_TRADE_ID = #{totleTradeId} and TPD.Trade_Status='01'
and TPD.TRADE_ID=#{busiCode}

mapper.update:
