set t.trade_status = #{tradeStatus}
where t.quote_id = #{totleTradeId,jdbcType=VARCHAR}

update IBU_QUOTE_CREP t
set t.trade_status = #{tradeStatus}
where t.quote_id = #{totleTradeId,jdbcType=VARCHAR}

