    select count(*) qty from wfl_reg_fin_product_deal_total  where TOTLE_TRADE_ID=#{tradeId,jdbcType=VARCHAR}
    union all
    select count(*) qty from reg_fin_product_deal_total  where TOTLE_TRADE_ID=#{tradeId,jdbcType=VARCHAR}
) t

