set t.dealtext = decode(t.dealtext, '-', '', t.dealtext) || #{remark}
where t.fedealno = #{exeId,jdbcType=VARCHAR}

mapper.select:
select exe_id exeId
 from trdquto_match_info
 where trd_id =#{bizCode,jdbcType=VARCHAR}

SELECT TPDA.Entrust_Id entrustId, TPDA.PORTFOLIO_ID portfolioId, pp.PORTFOLIO_NAME portfolioName, TPD.TRADE_AMT tradeAmt, ttft.fee_amt jyFeeAmt, ttft1.fee_amt jsFeeAmt, ftp.m_int_amt as mintAmt, ftp.m_trade_amt as fpriceAmt, pledges.disFaceValue as disFaceValue, EE.PRICE_MODEL as priceModel, ftp.int_rate*100 as tradeYield FROM TRD_PRODUCT_DEAL TPD INNER JOIN TRD_PRODUCT_DEAL_ADD TPDA on TPD.TRADE_ID = TPDA.TRADE_ID
inner JOIN PTL_PORTFOLIO_AUTHORITY PPA ON TPDA.portfolio_id = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userName}
LEFT JOIN PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = TPDA.PORTFOLIO_ID LEFT JOIN TRD_TRADE_FEE_DETAIL ttft ON tpd.trade_id = ttft.trade_id AND ttft.fee_type =#{feeType06} LEFT JOIN TRD_TRADE_FEE_DETAIL ttft1 ON tpd.trade_id = ttft1.trade_id AND ttft1.fee_type =#{feeType08} LEFT JOIN ETR_ENTRUST ee ON TPDA.Entrust_Id = ee.entrust_id left join fin_trade_product ftp on ftp.finprod_id=TPD.TRADE_ID left join (select pledge.finprod_id,sum(pledge.pledge_number*100) as disFaceValue from FIN_DEAL_PLEDGE pledge group by pledge.finprod_id)pledges on ftp.finprod_id=pledges.finprod_id where TPD.TOTLE_TRADE_ID = #{totleTradeId} and TPD.Trade_Status='01'
and TPD.TRADE_ID=#{busiCode}

SELECT CASE WHEN FPI.ISSUE_CLASS = #{ISSUE_CLASS_02} AND FPI.TENDER_TYPE IN(#{TENDER_TYPE_01},#{TENDER_TYPE_02}) THEN FPI.ISSUE_DATE WHEN(FPI.ISSUE_CLASS = #{ISSUE_CLASS_02} AND(FPI.TENDER_TYPE IS NULL OR FPI.TENDER_TYPE IN(#{TENDER_TYPE_03},#{TENDER_TYPE_04}))) OR FPI.ISSUE_CLASS = #{ISSUE_CLASS_03} THEN FPI.TENDER_SDATE END AS bidDateStart, CASE WHEN FPI.ISSUE_CLASS = #{ISSUE_CLASS_02} AND FPI.TENDER_TYPE IN(#{TENDER_TYPE_01},#{TENDER_TYPE_02}) THEN FPI.ISSUE_DATE WHEN(FPI.ISSUE_CLASS = #{ISSUE_CLASS_02} AND(FPI.TENDER_TYPE IS NULL OR FPI.TENDER_TYPE IN(#{TENDER_TYPE_03},#{TENDER_TYPE_04}))) OR FPI.ISSUE_CLASS = #{ISSUE_CLASS_03} THEN FPI.TENDER_EDATE END AS bidDateEnd, FP.FINPROD_ID finprodId, FP.FINPROD_MARKET_ID finprodMarketId, FP.FINPROD_ABBR finprodAbbr, m1.PARTY_ABBR as traderidStr, TFPDT.COUNTER_ID counterId, mcci.counter_name as counterIdStr, FPI.TENDER_TARGET tenderTarget, TFPDT.CCY ccy, TFPDT.TRADE_MARKET tradeMarket, TFPDT.TRADE_MARKET_MODE tradeMarketMode, BO.PAY_DATE payDate, BO.ASSIGN_REGDATE assignRegdate, BO.ONMARKET_DATE onmarketDate, BO.BID_MODLE bidModle, BO.PAY_TYPE payType, EEBP.BID_PRIN_AMT bidPrinAmt, TFPDT.PRIN_AMT/10000 prinAmt, BO.WIN_PRICE winPrice, TFPDT.UNIT_CPRICE unitCprice, TFPDT.UNIT_INT unitInt, TFPDT.FEE_AMT settleFeeAmt, BO.BID_ID bidId, TFPDT.REMARK remark, TFPDT.UNIT_FPRICE unitFprice, TFPDT.CPRICE_AMT cpriceAmt, TFPDT.INT_AMT intAmt, TFPDT.TRADE_AMT tradeAmt FROM TRD_FIN_PRODUCT_DEAL_TOTAL TFPDT LEFT JOIN FIN_PRODUCT FP ON FP.FINPROD_ID = TFPDT.FINPROD_ID LEFT JOIN FIN_PRODUCT_ISSUE FPI ON FPI.FINPROD_ID = FP.FINPROD_ID LEFT JOIN BID_ORDER BO ON BO.TRADE_STATUS = #{TRADE_STATUS_01} AND BO.BID_ID = TFPDT.B_TRADE_ID AND BO.BID_MODLE = #{WIN_TYPE_03} LEFT JOIN ( select TPD.TOTLE_TRADE_ID, SUM(EEBP.BID_PRIN_AMT) BID_PRIN_AMT from TRD_PRODUCT_DEAL TPD LEFT JOIN TRD_PRODUCT_DEAL_ADD TPDA ON TPD.TRADE_ID = TPDA.TRADE_ID LEFT JOIN ETR_ENTRUST EE ON EE.ENTRUST_ID = TPDA.ENTRUST_ID LEFT JOIN ETR_ENTRUST_BID_PRICE EEBP ON EEBP.ENTRUST_ID = EE.ENTRUST_ID AND EEBP.PORTFOLIO_ID = TPDA.PORTFOLIO_ID GROUP BY TPD.TOTLE_TRADE_ID ) EEBP ON TFPDT.TOTLE_TRADE_ID = EEBP.TOTLE_TRADE_ID LEFT JOIN MST_CFETS_CUSTOMER_INFO m1 on TFPDT.TRADER=m1.PARTY_ID LEFT JOIN MST_COUNTER_PARTY mcci ON TFPDT.COUNTER_ID = mcci.counter_id WHERE TFPDT.TRADE_STATUS = #{TRADE_STATUS_01}
AND TFPDT.TOTLE_TRADE_ID IN (SELECT TOTLE_TRADE_ID FROM TRD_PRODUCT_DEAL WHERE TRADE_ID = #{tradeId})
AND TFPDT.TOTLE_TRADE_ID = #{totleTradeId}

SELECT BO.DIP_TYPE dipType, TPDA.ENTRUST_ID entrustId, PP.PORTFOLIO_NAME portfolioName, TPD.PRIN_AMT/10000 prinAmt, TPD.FEE_AMT prinAmt, TPD.TRADE_AMT tradeAmt, TPD.INT_AMT intAmt, TPD.TRADE_AMT payAmt, BRBP.BID_PRICE BidPrice, TPD.INV_AIM invAim, TPD.SEC_MANAGE_ACCT_ID secManageAcctId, STLINFO.SEC_ACCT_NAME secManageAcctIdStr, SU.REAL_NAME invManagerId FROM TRD_FIN_PRODUCT_DEAL_TOTAL TFPDT LEFT JOIN TRD_PRODUCT_DEAL TPD ON TPD.TOTLE_TRADE_ID = TFPDT.TOTLE_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD TPDA ON TPD.TRADE_ID = TPDA.TRADE_ID LEFT JOIN PTL_PORTFOLIO PP ON PP.PORTFOLIO_ID = TPDA.PORTFOLIO_ID LEFT JOIN BID_ORDER BO ON BO.TRADE_STATUS = #{TRADE_STATUS_01} AND BO.BID_ID = TFPDT.B_TRADE_ID AND BO.BID_MODLE = #{WIN_TYPE_03} LEFT JOIN BID_ORDER_BID_PRICE BRBP ON BRBP.BID_ID = BO.BID_ID AND BRBP.ENTRUST_ID = TPDA.ENTRUST_ID AND BRBP.PORTFOLIO_ID = TPDA.PORTFOLIO_ID AND BRBP.SEC_ACCT_ID = TFPDT.SEC_MANAGE_ACCT_ID LEFT JOIN ETR_ENTRUST EE ON EE.ENTRUST_ID = TPDA.ENTRUST_ID LEFT JOIN ETR_ENTRUST_DETAIL EED ON EED.ENTRUST_ID = EE.ENTRUST_ID AND EED.PORTFOLIO_ID = TPDA.PORTFOLIO_ID LEFT JOIN ETR_ENTRUST_BID_PRICE EEBP ON EEBP.ENTRUST_ID = EE.ENTRUST_ID AND EEBP.PORTFOLIO_ID = EED.PORTFOLIO_ID AND EEBP.BID_PRICE = BRBP.BID_PRICE LEFT JOIN STL_SEC_ACCT_INFO STLINFO ON TPD.SEC_MANAGE_ACCT_ID=STLINFO.SEC_ACCT_ID LEFT JOIN SYS_USER SU ON EE.INV_MANAGER_ID = SU.USER_NAME WHERE TFPDT.TRADE_STATUS = #{TRADE_STATUS_01}
AND TPD.TRADE_ID = #{tradeId}
AND TFPDT.TOTLE_TRADE_ID = #{totleTradeId}

SELECT CASE WHEN FPI.ISSUE_CLASS = #{ISSUE_CLASS_02} AND FPI.TENDER_TYPE IN(#{TENDER_TYPE_01},#{TENDER_TYPE_02}) THEN FPI.ISSUE_DATE WHEN(FPI.ISSUE_CLASS = #{ISSUE_CLASS_02} AND(FPI.TENDER_TYPE IS NULL OR FPI.TENDER_TYPE IN(#{TENDER_TYPE_03},#{TENDER_TYPE_04}))) OR FPI.ISSUE_CLASS = #{ISSUE_CLASS_03} THEN FPI.TENDER_SDATE END AS bidDateStart, CASE WHEN FPI.ISSUE_CLASS = #{ISSUE_CLASS_02} AND FPI.TENDER_TYPE IN(#{TENDER_TYPE_01},#{TENDER_TYPE_02}) THEN FPI.ISSUE_DATE WHEN(FPI.ISSUE_CLASS = #{ISSUE_CLASS_02} AND(FPI.TENDER_TYPE IS NULL OR FPI.TENDER_TYPE IN(#{TENDER_TYPE_03},#{TENDER_TYPE_04}))) OR FPI.ISSUE_CLASS = #{ISSUE_CLASS_03} THEN FPI.TENDER_EDATE END AS bidDateEnd, FP.FINPROD_ID finprodId, FP.FINPROD_MARKET_ID finprodMarketId, FP.FINPROD_ABBR finprodAbbr, TFPDT.TRADER trader, m1.PARTY_ABBR as traderidStr, TFPDT.COUNTER_ID counterId, mcci.counter_name as counterIdStr, FPI.TENDER_TARGET tenderTarget, TFPDT.CCY ccy, TFPDT.TRADE_MARKET tradeMarket, TFPDT.TRADE_MARKET_MODE tradeMarketMode, BRT.PAY_DATE payDate, BRT.CREDITOR_DEBT_DATE assignRegdate, BO.ONMARKET_DATE onmarketDate, BO.BID_MODLE bidModle, BO.PAY_TYPE payType, EEBP.WIN_PRIN_AMT/10000 bidPrinAmt, TFPDT.PRIN_AMT/10000 prinAmt, BRT.WIN_PRICE winPrice, TFPDT.FEE_AMT settleFeeAmt, BO.BID_ID bidId, TFPDT.REMARK remark, TFPDT.UNIT_CPRICE unitCprice, TFPDT.UNIT_INT unitInt, TFPDT.UNIT_FPRICE unitFprice, TFPDT.CPRICE_AMT cpriceAmt, TFPDT.INT_AMT intAmt, TFPDT.TRADE_AMT tradeAmt FROM TRD_FIN_PRODUCT_DEAL_TOTAL TFPDT LEFT JOIN FIN_PRODUCT FP ON FP.FINPROD_ID = TFPDT.FINPROD_ID LEFT JOIN FIN_PRODUCT_ISSUE FPI ON FPI.FINPROD_ID = FP.FINPROD_ID LEFT JOIN BID_RESULT_TOTAL BRT ON BRT.TOTAL_WIN_ID = TFPDT.B_TRADE_ID AND BRT.STATUS = #{STATUS_VALID_01} LEFT JOIN BID_ORDER BO ON BO.TRADE_STATUS = #{TRADE_STATUS_01} AND BO.IS_CANCEL = 'N' AND BO.BID_ID = BRT.BID_ID AND BO.BID_MODLE IN(#{WIN_TYPE_01},#{WIN_TYPE_02}) LEFT JOIN ( select TPD.TOTLE_TRADE_ID ,BRBP.BID_ID, SUM(BRBP.WIN_PRIN_AMT) WIN_PRIN_AMT from TRD_PRODUCT_DEAL TPD LEFT JOIN TRD_PRODUCT_DEAL_ADD TPDA ON TPDA.TRADE_ID = TPD.TRADE_ID LEFT JOIN BID_ORDER_BID_PRICE BRBP ON BRBP.ENTRUST_ID = TPDA.ENTRUST_ID AND BRBP.PORTFOLIO_ID = TPDA.PORTFOLIO_ID AND BRBP.SEC_ACCT_ID = TPD.SEC_MANAGE_ACCT_ID GROUP BY TPD.TOTLE_TRADE_ID,BRBP.BID_ID ) EEBP ON TFPDT.TOTLE_TRADE_ID = EEBP.TOTLE_TRADE_ID AND BO.BID_ID = EEBP.BID_ID LEFT JOIN MST_CFETS_CUSTOMER_INFO m1 on TFPDT.TRADER=m1.PARTY_ID LEFT JOIN MST_COUNTER_PARTY mcci ON TFPDT.COUNTER_ID = mcci.counter_id WHERE TFPDT.TRADE_STATUS = #{TRADE_STATUS_01}
AND TFPDT.TOTLE_TRADE_ID IN (SELECT TOTLE_TRADE_ID FROM TRD_PRODUCT_DEAL WHERE TRADE_ID = #{tradeId})
AND TFPDT.TOTLE_TRADE_ID = #{totleTradeId}

SELECT BRT.WIN_TYPE dipType, EEBP.ENTRUST_ID entrustId, PP.PORTFOLIO_NAME portfolioName, BRBP.WIN_PRIN_AMT/10000 winPrinAmt, BRD.THE_WIN_PRINAMT/10000 theWinPrinamt, BRD.ACT_WIN_PRINAMT/10000 actWinPrinamt, BRD.BID_PRICE bidPrice, BRD.WIN_PRICE winPrice, BRD.WIN_CPRICE winCprice, BRD.INT_AMT intAmt, BRD.PAY_AMT payAmt, BRD.SETT_FEE_AMT settleFeeAmt, BRD.INV_AIM invAim, BRD.SEC_ACCT_ID secManageAcctId, STLINFO.SEC_ACCT_NAME secManageAcctIdStr, SU.REAL_NAME invManagerId FROM TRD_FIN_PRODUCT_DEAL_TOTAL TFPDT LEFT JOIN TRD_PRODUCT_DEAL TPD ON TPD.TOTLE_TRADE_ID = TFPDT.TOTLE_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD TPDA ON TPD.TRADE_ID = TPDA.TRADE_ID LEFT JOIN BID_RESULT_TOTAL BRT ON BRT.TOTAL_WIN_ID = TFPDT.B_TRADE_ID AND BRT.STATUS = #{STATUS_VALID_01} LEFT JOIN BID_RESULT_DETAIL BRD ON BRD.TOTAL_WIN_ID = BRT.TOTAL_WIN_ID AND BRD.ENTRUST_ID = TPDA.ENTRUST_ID AND BRD.PORTFOLIO_ID = TPDA.PORTFOLIO_ID AND BRD.SEC_ACCT_ID = TPD.SEC_MANAGE_ACCT_ID LEFT JOIN BID_ORDER BO ON BO.TRADE_STATUS = #{TRADE_STATUS_01} AND BO.IS_CANCEL = 'N' AND BO.BID_ID = BRT.BID_ID AND BO.BID_MODLE IN(#{WIN_TYPE_01},#{WIN_TYPE_02}) LEFT JOIN BID_ORDER_BID_PRICE BRBP ON BRBP.BID_ID = BO.BID_ID AND BRBP.ENTRUST_ID = TPDA.ENTRUST_ID AND BRBP.PORTFOLIO_ID = TPDA.PORTFOLIO_ID AND BRBP.SEC_ACCT_ID = TPD.SEC_MANAGE_ACCT_ID LEFT JOIN PTL_PORTFOLIO PP ON BRBP.PORTFOLIO_ID = TPDA.PORTFOLIO_ID LEFT JOIN ETR_ENTRUST EE ON EE.ENTRUST_ID = TPDA.ENTRUST_ID LEFT JOIN ETR_ENTRUST_DETAIL EED ON EED.ENTRUST_ID = EE.ENTRUST_ID AND EED.PORTFOLIO_ID = TPDA.PORTFOLIO_ID LEFT JOIN ETR_ENTRUST_BID_PRICE EEBP ON EEBP.ENTRUST_ID = EE.ENTRUST_ID AND EEBP.PORTFOLIO_ID = EED.PORTFOLIO_ID AND EEBP.BID_PRICE = BRBP.BID_PRICE LEFT JOIN STL_SEC_ACCT_INFO STLINFO ON TPD.SEC_MANAGE_ACCT_ID=STLINFO.SEC_ACCT_ID LEFT JOIN SYS_USER SU ON EE.INV_MANAGER_ID = SU.USER_NAME WHERE TFPDT.TRADE_STATUS = #{TRADE_STATUS_01}
AND TPD.TRADE_ID = #{tradeId}
AND TFPDT.TOTLE_TRADE_ID = #{totleTradeId}

SELECT BO.OU_PARTY_ID ouPartyId, TFPDT.TRADER trader, m1.PARTY_ABBR as traderidStr, TFPDT.TRADE_DATE tradeDate, FP.FINPROD_ID finprodId, FP.FINPROD_MARKET_ID finprodMarketId, FP.FINPROD_ABBR finprodAbbr, FP.COUPON_SPECIES couponSpecies, FPI.INT_TYPE intType, TFPDT.PS ps, TFPDT.TRADE_MARKET tradeMarket, TFPDT.TRADE_MARKET_MODE tradeMarketMode, TFPDT.TRADE_PLAT tradePlat, FPI.ISSUE_DATE issueDate, FPI.PAY_DATE payDate, FP.ISSUER issuer, TFPDT.CCY ccy, FP.ISSUE_PRICE issuePrice, TFPDT.RATE rate, TFPDT.PRIN_AMT/10000 subAmt, TFPDT.TRADE_AMT payAmt, TFPDT.FEE_AMT settleFeeAmt, TFPDT.REMARK remark FROM TRD_FIN_PRODUCT_DEAL_TOTAL TFPDT LEFT JOIN FIN_PRODUCT FP ON FP.FINPROD_ID = TFPDT.FINPROD_ID LEFT JOIN FIN_PRODUCT_ISSUE FPI ON FPI.FINPROD_ID = FP.FINPROD_ID LEFT JOIN TRDQUTO_MATCH_INFO TMI ON TMI.TRD_ID = TFPDT.TOTLE_TRADE_ID LEFT JOIN BID_ORDER BO ON BO.TRADE_STATUS = #{TRADE_STATUS_01} AND BO.BID_ID=TMI.PRE_TRADE_ID LEFT JOIN MST_CFETS_CUSTOMER_INFO m1 on TFPDT.TRADER=m1.PARTY_ID WHERE TFPDT.TRADE_STATUS = #{TRADE_STATUS_01}
AND TFPDT.TOTLE_TRADE_ID IN (SELECT TOTLE_TRADE_ID FROM TRD_PRODUCT_DEAL WHERE TRADE_ID = #{tradeId})
AND TFPDT.TOTLE_TRADE_ID = #{totleTradeId}

SELECT ROWNUM seqNo, BO.DIP_TYPE dipType, TPDA.ENTRUST_ID entrustId, PP.PORTFOLIO_NAME portfolioName, TPD.PRIN_AMT/10000 prinAmt, TPD.FEE_AMT feeAmt, TPD.INV_AIM invAim, TPD.SEC_MANAGE_ACCT_ID secManageAcctId, STLINFO.SEC_ACCT_NAME secManageAcctIdStr FROM TRD_FIN_PRODUCT_DEAL_TOTAL TFPDT LEFT JOIN TRD_PRODUCT_DEAL TPD ON TPD.TOTLE_TRADE_ID = TFPDT.TOTLE_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD TPDA ON TPDA.TRADE_ID = TPD.TRADE_ID LEFT JOIN PTL_PORTFOLIO PP ON PP.PORTFOLIO_ID = TPDA.PORTFOLIO_ID LEFT JOIN TRDQUTO_MATCH_INFO TMI ON TMI.TRD_ID = TFPDT.TOTLE_TRADE_ID LEFT JOIN BID_ORDER BO ON BO.TRADE_STATUS = #{TRADE_STATUS_01} AND BO.BID_ID=TMI.PRE_TRADE_ID LEFT JOIN STL_SEC_ACCT_INFO STLINFO ON TPD.SEC_MANAGE_ACCT_ID=STLINFO.SEC_ACCT_ID WHERE TFPDT.TRADE_STATUS = #{TRADE_STATUS_01}
AND TPD.TRADE_ID = #{tradeId}
AND TFPDT.TOTLE_TRADE_ID = #{totleTradeId}
